-- Aprenda se Divertindo · 79 · Baralho de cartões · trilha Fiscal (500 cartões)
-- Rode depois do 78-cartoes-tribunais.sql. Cole TUDO no SQL Editor e clique em Run. Pode rodar de novo sem problema.
--
-- Matérias: Contabilidade, AFO, Auditoria, Economia e Finanças, Legislação Aduaneira, Estatística e Fluência em Dados.
-- Português, Constitucional, Administrativo, Tributário, Previdenciário e as demais já usam os cartões das outras trilhas.
-- AFO também passa a valer na trilha Administrativa.
-- Cartões numerados a partir de 2.000.002.001. O jogo baixa os novos cartões sozinho.

insert into public.cartoes (id, trilha, materia, assunto, tipo, frente, verso, explicacao)
select id, trilha, materia, assunto, tipo, frente, verso, explicacao
from jsonb_to_recordset($c$[{"id": 2000002001, "trilha": "fiscal", "materia": "cont", "assunto": "Conceitos", "tipo": "pergunta", "frente": "Qual o objeto da contabilidade?", "verso": "O patrimônio das entidades.", "explicacao": "Objetivo: fornecer informações úteis sobre o patrimônio e suas variações."}, {"id": 2000002002, "trilha": "fiscal", "materia": "cont", "assunto": "Conceitos", "tipo": "pergunta", "frente": "O que é patrimônio?", "verso": "Conjunto de bens, direitos e obrigações de uma entidade.", "explicacao": ""}, {"id": 2000002003, "trilha": "fiscal", "materia": "cont", "assunto": "Conceitos", "tipo": "lacuna", "frente": "Equação patrimonial: Ativo = Passivo + ___.", "verso": "Patrimônio Líquido.", "explicacao": "A = P + PL."}, {"id": 2000002004, "trilha": "fiscal", "materia": "cont", "assunto": "Conceitos", "tipo": "pares", "frente": "Situação líquida positiva x nula x negativa.", "verso": "Positiva: Ativo > Passivo (PL positivo). Nula: Ativo = Passivo. Negativa (passivo a descoberto): Ativo < Passivo.", "explicacao": ""}, {"id": 2000002005, "trilha": "fiscal", "materia": "cont", "assunto": "Conceitos", "tipo": "pares", "frente": "Bens x direitos x obrigações.", "verso": "Bens: coisas que satisfazem necessidades e podem ser avaliadas (caixa, estoques, imóveis). Direitos: valores a receber (clientes, duplicatas a receber). Obrigações: dívidas com terceiros (fornecedores, salários a pagar).", "explicacao": ""}, {"id": 2000002006, "trilha": "fiscal", "materia": "cont", "assunto": "Conceitos", "tipo": "pares", "frente": "Bens tangíveis x intangíveis.", "verso": "Tangíveis: têm existência física (máquinas, veículos). Intangíveis: sem corpo físico (marcas, patentes, softwares).", "explicacao": ""}, {"id": 2000002007, "trilha": "fiscal", "materia": "cont", "assunto": "Conceitos", "tipo": "pergunta", "frente": "O que são as origens e as aplicações de recursos?", "verso": "Origens: Passivo e Patrimônio Líquido (de onde vêm os recursos). Aplicações: Ativo (onde estão aplicados).", "explicacao": "Por isso o total do Ativo é igual ao do Passivo mais PL."}, {"id": 2000002008, "trilha": "fiscal", "materia": "cont", "assunto": "Estrutura conceitual", "tipo": "pergunta", "frente": "Quais as características qualitativas fundamentais da informação contábil?", "verso": "Relevância e representação fidedigna.", "explicacao": "CPC 00 (Estrutura Conceitual)."}, {"id": 2000002009, "trilha": "fiscal", "materia": "cont", "assunto": "Estrutura conceitual", "tipo": "pergunta", "frente": "Quais as características qualitativas de melhoria?", "verso": "Comparabilidade, verificabilidade, tempestividade e compreensibilidade.", "explicacao": "CPC 00."}, {"id": 2000002010, "trilha": "fiscal", "materia": "cont", "assunto": "Estrutura conceitual", "tipo": "pergunta", "frente": "Qual o pressuposto básico das demonstrações contábeis?", "verso": "Continuidade operacional: presume-se que a entidade continuará operando no futuro previsível.", "explicacao": "CPC 00."}, {"id": 2000002011, "trilha": "fiscal", "materia": "cont", "assunto": "Estrutura conceitual", "tipo": "pergunta", "frente": "Como o CPC 00 define ativo?", "verso": "Recurso econômico presente controlado pela entidade como resultado de eventos passados.", "explicacao": "Recurso econômico: direito com potencial de produzir benefícios econômicos."}, {"id": 2000002012, "trilha": "fiscal", "materia": "cont", "assunto": "Estrutura conceitual", "tipo": "pergunta", "frente": "Como o CPC 00 define passivo?", "verso": "Obrigação presente da entidade de transferir um recurso econômico como resultado de eventos passados.", "explicacao": ""}, {"id": 2000002013, "trilha": "fiscal", "materia": "cont", "assunto": "Estrutura conceitual", "tipo": "pergunta", "frente": "O que é a primazia da essência sobre a forma?", "verso": "As transações devem ser contabilizadas conforme sua realidade econômica, e não apenas sua forma jurídica.", "explicacao": "Ex.: arrendamento financeiro registrado como ativo."}, {"id": 2000002014, "trilha": "fiscal", "materia": "cont", "assunto": "Escrituração", "tipo": "pergunta", "frente": "O que diz o método das partidas dobradas?", "verso": "Para todo débito há um crédito de igual valor: a soma dos débitos é igual à soma dos créditos.", "explicacao": "Frei Luca Pacioli (1494)."}, {"id": 2000002015, "trilha": "fiscal", "materia": "cont", "assunto": "Escrituração", "tipo": "pares", "frente": "Contas de ativo e despesa x contas de passivo, PL e receita.", "verso": "Ativo e despesa: aumentam por débito e diminuem por crédito (natureza devedora). Passivo, PL e receita: aumentam por crédito e diminuem por débito (natureza credora).", "explicacao": "Base de todo lançamento."}, {"id": 2000002016, "trilha": "fiscal", "materia": "cont", "assunto": "Escrituração", "tipo": "pergunta", "frente": "Quais os elementos essenciais de um lançamento?", "verso": "Local e data, conta debitada, conta creditada, histórico e valor.", "explicacao": ""}, {"id": 2000002017, "trilha": "fiscal", "materia": "cont", "assunto": "Escrituração", "tipo": "pares", "frente": "Livro Diário x Livro Razão.", "verso": "Diário: registro cronológico de todas as operações; é obrigatório. Razão: registro por conta, mostrando a movimentação e o saldo de cada uma.", "explicacao": "O Razão é obrigatório pela legislação do IR para empresas no lucro real."}, {"id": 2000002018, "trilha": "fiscal", "materia": "cont", "assunto": "Escrituração", "tipo": "pergunta", "frente": "O que é balancete de verificação?", "verso": "Relação das contas com seus saldos devedores e credores, para verificar se a soma dos débitos é igual à dos créditos.", "explicacao": "Não garante ausência de erros (ex.: conta trocada)."}, {"id": 2000002019, "trilha": "fiscal", "materia": "cont", "assunto": "Escrituração", "tipo": "pares", "frente": "Fórmulas de lançamento de 1ª, 2ª, 3ª e 4ª fórmulas.", "verso": "1ª: uma conta devedora e uma credora. 2ª: uma devedora e várias credoras. 3ª: várias devedoras e uma credora. 4ª: várias devedoras e várias credoras.", "explicacao": ""}, {"id": 2000002020, "trilha": "fiscal", "materia": "cont", "assunto": "Escrituração", "tipo": "pergunta", "frente": "Como se registra a compra de mercadorias a prazo?", "verso": "D – Estoque de mercadorias; C – Fornecedores.", "explicacao": "Fato permutativo."}, {"id": 2000002021, "trilha": "fiscal", "materia": "cont", "assunto": "Escrituração", "tipo": "pergunta", "frente": "Como se registra o pagamento de salários do mês, à vista?", "verso": "D – Despesa com salários; C – Caixa (ou Bancos).", "explicacao": "Fato modificativo diminutivo."}, {"id": 2000002022, "trilha": "fiscal", "materia": "cont", "assunto": "Fatos contábeis", "tipo": "pares", "frente": "Fato permutativo x modificativo x misto.", "verso": "Permutativo: troca entre elementos patrimoniais, sem alterar o PL. Modificativo: altera o PL (receita ou despesa). Misto: permuta e modificação ao mesmo tempo.", "explicacao": "Ex. de misto: venda de mercadoria com lucro."}, {"id": 2000002023, "trilha": "fiscal", "materia": "cont", "assunto": "Fatos contábeis", "tipo": "pergunta", "frente": "O pagamento de uma dívida com fornecedor altera o PL?", "verso": "Não. É fato permutativo: diminui o caixa e o passivo no mesmo valor.", "explicacao": ""}, {"id": 2000002024, "trilha": "fiscal", "materia": "cont", "assunto": "Fatos contábeis", "tipo": "pergunta", "frente": "O recebimento de juros altera o PL?", "verso": "Sim, aumenta. É fato modificativo aumentativo.", "explicacao": ""}, {"id": 2000002025, "trilha": "fiscal", "materia": "cont", "assunto": "Balanço patrimonial", "tipo": "pergunta", "frente": "Como se divide o ativo no balanço (Lei 6.404)?", "verso": "Ativo circulante e ativo não circulante (realizável a longo prazo, investimentos, imobilizado e intangível).", "explicacao": "Lei 6.404/1976, art. 178."}, {"id": 2000002026, "trilha": "fiscal", "materia": "cont", "assunto": "Balanço patrimonial", "tipo": "pergunta", "frente": "Como se divide o passivo no balanço?", "verso": "Passivo circulante e passivo não circulante.", "explicacao": "Mais o patrimônio líquido."}, {"id": 2000002027, "trilha": "fiscal", "materia": "cont", "assunto": "Balanço patrimonial", "tipo": "pergunta", "frente": "Quais os grupos do patrimônio líquido?", "verso": "Capital social, reservas de capital, ajustes de avaliação patrimonial, reservas de lucros, ações em tesouraria e prejuízos acumulados.", "explicacao": "Lei 6.404/1976, art. 178, § 2º, III."}, {"id": 2000002028, "trilha": "fiscal", "materia": "cont", "assunto": "Balanço patrimonial", "tipo": "pergunta", "frente": "Qual o critério para classificar no circulante?", "verso": "Direitos realizáveis e obrigações vencíveis até o término do exercício social seguinte.", "explicacao": "Se o ciclo operacional for maior que o exercício, usa-se o ciclo."}, {"id": 2000002029, "trilha": "fiscal", "materia": "cont", "assunto": "Balanço patrimonial", "tipo": "pergunta", "frente": "Como se ordenam as contas do ativo?", "verso": "Em ordem decrescente de grau de liquidez.", "explicacao": "Passivo: ordem decrescente de exigibilidade."}, {"id": 2000002030, "trilha": "fiscal", "materia": "cont", "assunto": "Balanço patrimonial", "tipo": "pergunta", "frente": "Empréstimos a sócios e diretores são classificados onde?", "verso": "No ativo realizável a longo prazo, mesmo que vençam no curto prazo, quando não constituírem negócios usuais.", "explicacao": "Lei 6.404/1976, art. 179, II."}, {"id": 2000002031, "trilha": "fiscal", "materia": "cont", "assunto": "Balanço patrimonial", "tipo": "pares", "frente": "Investimentos x imobilizado x intangível.", "verso": "Investimentos: participações permanentes e bens não usados na atividade (imóvel para renda). Imobilizado: bens corpóreos usados na atividade (máquinas, prédio-sede). Intangível: bens incorpóreos (marcas, softwares).", "explicacao": "Lei 6.404/1976, art. 179."}, {"id": 2000002032, "trilha": "fiscal", "materia": "cont", "assunto": "Balanço patrimonial", "tipo": "pergunta", "frente": "Onde se classifica a conta Duplicatas Descontadas?", "verso": "No passivo circulante, como empréstimo (de acordo com as normas atuais).", "explicacao": "Antes era retificadora do ativo."}, {"id": 2000002033, "trilha": "fiscal", "materia": "cont", "assunto": "Contas retificadoras", "tipo": "pergunta", "frente": "Cite contas retificadoras do ativo.", "verso": "Depreciação acumulada, amortização acumulada, exaustão acumulada, perdas estimadas em créditos de liquidação duvidosa e ajuste a valor presente.", "explicacao": "Têm saldo credor."}, {"id": 2000002034, "trilha": "fiscal", "materia": "cont", "assunto": "Contas retificadoras", "tipo": "pergunta", "frente": "Cite contas retificadoras do PL.", "verso": "Ações em tesouraria, prejuízos acumulados e capital a integralizar.", "explicacao": "Têm saldo devedor."}, {"id": 2000002035, "trilha": "fiscal", "materia": "cont", "assunto": "Depreciação", "tipo": "pares", "frente": "Depreciação x amortização x exaustão.", "verso": "Depreciação: perda de valor de bens tangíveis (máquinas, veículos). Amortização: de intangíveis com vida útil definida e direitos de prazo limitado. Exaustão: de recursos naturais (minas, florestas).", "explicacao": ""}, {"id": 2000002036, "trilha": "fiscal", "materia": "cont", "assunto": "Depreciação", "tipo": "pergunta", "frente": "Terrenos sofrem depreciação?", "verso": "Não. Têm vida útil ilimitada.", "explicacao": "Edificações sobre o terreno, sim."}, {"id": 2000002037, "trilha": "fiscal", "materia": "cont", "assunto": "Depreciação", "tipo": "pergunta", "frente": "Como se calcula a depreciação pelo método linear?", "verso": "(Custo − valor residual) ÷ vida útil.", "explicacao": "Ex.: (R$ 50.000 − 5.000) ÷ 5 anos = R$ 9.000 por ano."}, {"id": 2000002038, "trilha": "fiscal", "materia": "cont", "assunto": "Depreciação", "tipo": "pergunta", "frente": "Qual o lançamento da depreciação?", "verso": "D – Despesa de depreciação; C – Depreciação acumulada.", "explicacao": ""}, {"id": 2000002039, "trilha": "fiscal", "materia": "cont", "assunto": "Depreciação", "tipo": "pergunta", "frente": "O que é o valor contábil de um bem do imobilizado?", "verso": "Custo menos depreciação acumulada e perdas por redução ao valor recuperável.", "explicacao": ""}, {"id": 2000002040, "trilha": "fiscal", "materia": "cont", "assunto": "Ativos", "tipo": "pergunta", "frente": "O que é teste de impairment (CPC 01)?", "verso": "Verificar se o valor contábil de um ativo excede seu valor recuperável; se exceder, reconhece-se perda.", "explicacao": "Valor recuperável: o maior entre valor justo líquido de despesa de venda e valor em uso."}, {"id": 2000002041, "trilha": "fiscal", "materia": "cont", "assunto": "Ativos", "tipo": "pergunta", "frente": "O ágio por expectativa de rentabilidade futura (goodwill) é amortizado?", "verso": "Não. Está sujeito apenas ao teste anual de impairment.", "explicacao": "CPC 01 e CPC 15."}, {"id": 2000002042, "trilha": "fiscal", "materia": "cont", "assunto": "Ativos", "tipo": "pergunta", "frente": "O que é a PECLD (provisão para devedores duvidosos)?", "verso": "Estimativa de perdas com clientes que provavelmente não pagarão; reduz as contas a receber.", "explicacao": "D – Despesa com PECLD; C – PECLD (retificadora)."}, {"id": 2000002043, "trilha": "fiscal", "materia": "cont", "assunto": "Estoques", "tipo": "pergunta", "frente": "Qual o critério de avaliação de estoques segundo o CPC 16?", "verso": "Pelo menor valor entre o custo e o valor realizável líquido.", "explicacao": ""}, {"id": 2000002044, "trilha": "fiscal", "materia": "cont", "assunto": "Estoques", "tipo": "pares", "frente": "PEPS x média ponderada móvel.", "verso": "PEPS (FIFO): saem primeiro as mercadorias mais antigas; o estoque final fica com os custos mais recentes. Média ponderada: cada saída usa o custo médio atualizado após cada compra.", "explicacao": "O UEPS (LIFO) não é aceito pelo CPC 16 nem pelo fisco."}, {"id": 2000002045, "trilha": "fiscal", "materia": "cont", "assunto": "Estoques", "tipo": "pergunta", "frente": "Em período de inflação, qual método gera maior lucro: PEPS ou média?", "verso": "PEPS, porque o custo das vendas fica com os preços mais antigos (menores).", "explicacao": ""}, {"id": 2000002046, "trilha": "fiscal", "materia": "cont", "assunto": "Estoques", "tipo": "lacuna", "frente": "CMV = Estoque inicial + Compras − ___.", "verso": "Estoque final.", "explicacao": "Custo das Mercadorias Vendidas pelo inventário periódico."}, {"id": 2000002047, "trilha": "fiscal", "materia": "cont", "assunto": "Estoques", "tipo": "pergunta", "frente": "Os fretes sobre compras integram o custo do estoque?", "verso": "Sim, quando pagos pelo comprador.", "explicacao": "Também seguros e impostos não recuperáveis."}, {"id": 2000002048, "trilha": "fiscal", "materia": "cont", "assunto": "Estoques", "tipo": "pergunta", "frente": "Como se trata o ICMS recuperável na compra de mercadorias?", "verso": "Não integra o custo; é registrado como ICMS a recuperar no ativo.", "explicacao": ""}, {"id": 2000002049, "trilha": "fiscal", "materia": "cont", "assunto": "Estoques", "tipo": "pares", "frente": "Devolução de compras x abatimento sobre compras.", "verso": "Devolução: a mercadoria volta ao fornecedor. Abatimento: redução de preço concedida pelo fornecedor, sem devolução. Ambos reduzem o custo das compras.", "explicacao": ""}, {"id": 2000002050, "trilha": "fiscal", "materia": "cont", "assunto": "DRE", "tipo": "pergunta", "frente": "Qual a estrutura básica da DRE?", "verso": "Receita bruta (−) deduções = receita líquida (−) CMV = lucro bruto (−) despesas operacionais = resultado antes do IR (−) IR e CSLL (−) participações = lucro líquido.", "explicacao": "Lei 6.404/1976, art. 187."}, {"id": 2000002051, "trilha": "fiscal", "materia": "cont", "assunto": "DRE", "tipo": "pergunta", "frente": "O que são deduções da receita bruta?", "verso": "Devoluções de vendas, abatimentos, descontos incondicionais e impostos sobre vendas (ICMS, PIS, Cofins, ISS).", "explicacao": ""}, {"id": 2000002052, "trilha": "fiscal", "materia": "cont", "assunto": "DRE", "tipo": "pares", "frente": "Desconto comercial (incondicional) x financeiro (condicional).", "verso": "Incondicional: concedido na nota fiscal, reduz a receita bruta. Condicional: depende de evento posterior (pagamento antecipado), é despesa financeira.", "explicacao": ""}, {"id": 2000002053, "trilha": "fiscal", "materia": "cont", "assunto": "DRE", "tipo": "pergunta", "frente": "Qual o lucro bruto se receita líquida é R$ 100 mil e CMV R$ 60 mil?", "verso": "R$ 40 mil.", "explicacao": "Lucro bruto = receita líquida − CMV."}, {"id": 2000002054, "trilha": "fiscal", "materia": "cont", "assunto": "DRE", "tipo": "pergunta", "frente": "As despesas financeiras são operacionais na DRE da Lei 6.404?", "verso": "Sim, a Lei 6.404 as inclui entre as despesas operacionais.", "explicacao": "Pelo CPC 26, devem aparecer separadamente."}, {"id": 2000002055, "trilha": "fiscal", "materia": "cont", "assunto": "DFC", "tipo": "pergunta", "frente": "Quais as três atividades da DFC?", "verso": "Operacionais, de investimento e de financiamento.", "explicacao": "CPC 03."}, {"id": 2000002056, "trilha": "fiscal", "materia": "cont", "assunto": "DFC", "tipo": "pares", "frente": "Método direto x indireto da DFC.", "verso": "Direto: mostra recebimentos e pagamentos brutos. Indireto: parte do lucro líquido e ajusta pelas despesas que não afetam o caixa (depreciação) e variações do capital de giro.", "explicacao": ""}, {"id": 2000002057, "trilha": "fiscal", "materia": "cont", "assunto": "DFC", "tipo": "pergunta", "frente": "A compra de máquina à vista entra em qual atividade da DFC?", "verso": "Atividade de investimento.", "explicacao": ""}, {"id": 2000002058, "trilha": "fiscal", "materia": "cont", "assunto": "DFC", "tipo": "pergunta", "frente": "A captação de empréstimo bancário entra em qual atividade da DFC?", "verso": "Atividade de financiamento.", "explicacao": "Pagamento de dividendos também é financiamento (em regra)."}, {"id": 2000002059, "trilha": "fiscal", "materia": "cont", "assunto": "DFC", "tipo": "pergunta", "frente": "Quem está dispensada de elaborar a DFC?", "verso": "A companhia fechada com patrimônio líquido inferior a R$ 2 milhões na data do balanço.", "explicacao": "Lei 6.404/1976, art. 176, § 6º."}, {"id": 2000002060, "trilha": "fiscal", "materia": "cont", "assunto": "DVA", "tipo": "pergunta", "frente": "Quem é obrigada a elaborar a DVA?", "verso": "As companhias abertas.", "explicacao": "Lei 6.404/1976, art. 176, V. Mostra a riqueza gerada e sua distribuição."}, {"id": 2000002061, "trilha": "fiscal", "materia": "cont", "assunto": "DVA", "tipo": "pergunta", "frente": "Entre quem a DVA distribui o valor adicionado?", "verso": "Pessoal, impostos, taxas e contribuições, remuneração de capitais de terceiros e remuneração de capitais próprios.", "explicacao": "CPC 09."}, {"id": 2000002062, "trilha": "fiscal", "materia": "cont", "assunto": "DMPL", "tipo": "pergunta", "frente": "O que mostra a DMPL?", "verso": "As mutações de todas as contas do patrimônio líquido durante o exercício.", "explicacao": "Engloba a DLPA."}, {"id": 2000002063, "trilha": "fiscal", "materia": "cont", "assunto": "Demonstrações", "tipo": "pergunta", "frente": "Quais demonstrações a Lei 6.404 exige ao fim de cada exercício?", "verso": "Balanço patrimonial, DLPA (ou DMPL), DRE, DFC e, se companhia aberta, DVA.", "explicacao": "Lei 6.404/1976, art. 176. As notas explicativas complementam."}, {"id": 2000002064, "trilha": "fiscal", "materia": "cont", "assunto": "Patrimônio líquido", "tipo": "pergunta", "frente": "Qual o limite da reserva legal?", "verso": "5% do lucro líquido por ano, até atingir 20% do capital social.", "explicacao": "Lei 6.404/1976, art. 193."}, {"id": 2000002065, "trilha": "fiscal", "materia": "cont", "assunto": "Patrimônio líquido", "tipo": "pergunta", "frente": "Qual o dividendo mínimo obrigatório se o estatuto for omisso?", "verso": "Metade do lucro líquido ajustado.", "explicacao": "Lei 6.404/1976, art. 202, I. Se o estatuto for omisso e for alterado depois, o mínimo é 25%."}, {"id": 2000002066, "trilha": "fiscal", "materia": "cont", "assunto": "Patrimônio líquido", "tipo": "pergunta", "frente": "O que compõe as reservas de capital?", "verso": "Ágio na emissão de ações, produto da alienação de partes beneficiárias e bônus de subscrição.", "explicacao": "Lei 6.404/1976, art. 182, § 1º."}, {"id": 2000002067, "trilha": "fiscal", "materia": "cont", "assunto": "Patrimônio líquido", "tipo": "pergunta", "frente": "O que são ações em tesouraria?", "verso": "Ações da própria companhia que ela recomprou; aparecem como redutoras do PL.", "explicacao": ""}, {"id": 2000002068, "trilha": "fiscal", "materia": "cont", "assunto": "Patrimônio líquido", "tipo": "pergunta", "frente": "A conta lucros acumulados pode ter saldo no balanço de S.A.?", "verso": "Não. O lucro deve ser todo destinado (reservas, dividendos ou aumento de capital).", "explicacao": "Lei 6.404/1976, art. 202, § 6º."}, {"id": 2000002069, "trilha": "fiscal", "materia": "cont", "assunto": "Análise", "tipo": "pergunta", "frente": "Fórmula da liquidez corrente.", "verso": "Ativo circulante ÷ passivo circulante.", "explicacao": "Maior que 1: folga financeira no curto prazo."}, {"id": 2000002070, "trilha": "fiscal", "materia": "cont", "assunto": "Análise", "tipo": "pergunta", "frente": "Fórmula da liquidez seca.", "verso": "(Ativo circulante − estoques) ÷ passivo circulante.", "explicacao": "Exclui os estoques, menos líquidos."}, {"id": 2000002071, "trilha": "fiscal", "materia": "cont", "assunto": "Análise", "tipo": "pergunta", "frente": "Fórmula da liquidez imediata.", "verso": "Disponível ÷ passivo circulante.", "explicacao": ""}, {"id": 2000002072, "trilha": "fiscal", "materia": "cont", "assunto": "Análise", "tipo": "pergunta", "frente": "Fórmula da liquidez geral.", "verso": "(Ativo circulante + realizável a longo prazo) ÷ (passivo circulante + passivo não circulante).", "explicacao": ""}, {"id": 2000002073, "trilha": "fiscal", "materia": "cont", "assunto": "Análise", "tipo": "pergunta", "frente": "O que mede o grau de endividamento (participação de capitais de terceiros)?", "verso": "Capitais de terceiros ÷ patrimônio líquido.", "explicacao": "Quanto maior, mais dependência de terceiros."}, {"id": 2000002074, "trilha": "fiscal", "materia": "cont", "assunto": "Análise", "tipo": "pergunta", "frente": "O que é capital circulante líquido?", "verso": "Ativo circulante − passivo circulante.", "explicacao": "Também chamado capital de giro líquido."}, {"id": 2000002075, "trilha": "fiscal", "materia": "cont", "assunto": "Análise", "tipo": "pergunta", "frente": "Fórmula do ROE (retorno sobre o patrimônio líquido).", "verso": "Lucro líquido ÷ patrimônio líquido.", "explicacao": ""}, {"id": 2000002076, "trilha": "fiscal", "materia": "cont", "assunto": "Análise", "tipo": "pergunta", "frente": "Fórmula do prazo médio de recebimento de vendas.", "verso": "(Clientes ÷ vendas a prazo) × 360 dias.", "explicacao": "Ciclo financeiro = PMRE + PMRV − PMPC."}, {"id": 2000002077, "trilha": "fiscal", "materia": "cont", "assunto": "Análise", "tipo": "pares", "frente": "Análise horizontal x vertical.", "verso": "Horizontal: compara a evolução de uma conta ao longo do tempo. Vertical: mostra o peso de cada conta em relação a um total (ativo total ou receita líquida).", "explicacao": ""}, {"id": 2000002078, "trilha": "fiscal", "materia": "cont", "assunto": "Análise", "tipo": "pares", "frente": "Ciclo operacional x ciclo financeiro.", "verso": "Operacional: da compra da mercadoria até o recebimento da venda (PMRE + PMRV). Financeiro (de caixa): da saída de caixa (pagamento ao fornecedor) até o recebimento (ciclo operacional − PMPC).", "explicacao": ""}, {"id": 2000002079, "trilha": "fiscal", "materia": "cont", "assunto": "Custos", "tipo": "pares", "frente": "Custo x despesa.", "verso": "Custo: gasto ligado à produção de bens ou serviços (matéria-prima, mão de obra direta). Despesa: gasto para obter receita, fora da produção (comissão de vendedores, aluguel do escritório).", "explicacao": ""}, {"id": 2000002080, "trilha": "fiscal", "materia": "cont", "assunto": "Custos", "tipo": "pares", "frente": "Custos diretos x indiretos.", "verso": "Diretos: identificados diretamente com o produto (matéria-prima). Indiretos: precisam de rateio (aluguel da fábrica, energia da fábrica).", "explicacao": ""}, {"id": 2000002081, "trilha": "fiscal", "materia": "cont", "assunto": "Custos", "tipo": "pares", "frente": "Custos fixos x variáveis.", "verso": "Fixos: não variam com o volume produzido (aluguel da fábrica). Variáveis: variam conforme a produção (matéria-prima).", "explicacao": "O custo fixo unitário cai quando a produção aumenta."}, {"id": 2000002082, "trilha": "fiscal", "materia": "cont", "assunto": "Custos", "tipo": "pares", "frente": "Custeio por absorção x variável.", "verso": "Absorção: todos os custos de produção (fixos e variáveis) vão para o produto; aceito pela legislação. Variável: só os variáveis vão para o produto; os fixos são despesa do período; útil para decisões gerenciais.", "explicacao": ""}, {"id": 2000002083, "trilha": "fiscal", "materia": "cont", "assunto": "Custos", "tipo": "pergunta", "frente": "O que é margem de contribuição unitária?", "verso": "Preço de venda − custos e despesas variáveis unitários.", "explicacao": "Indica quanto cada unidade contribui para cobrir os fixos e gerar lucro."}, {"id": 2000002084, "trilha": "fiscal", "materia": "cont", "assunto": "Custos", "tipo": "pergunta", "frente": "Fórmula do ponto de equilíbrio contábil em unidades.", "verso": "Custos e despesas fixos ÷ margem de contribuição unitária.", "explicacao": "No ponto de equilíbrio, lucro é zero."}, {"id": 2000002085, "trilha": "fiscal", "materia": "cont", "assunto": "Custos", "tipo": "pergunta", "frente": "O que é o custeio ABC?", "verso": "Custeio baseado em atividades: os custos indiretos são atribuídos às atividades e destas aos produtos por direcionadores de custo.", "explicacao": ""}, {"id": 2000002086, "trilha": "fiscal", "materia": "cont", "assunto": "Custos", "tipo": "lacuna", "frente": "Custo de produção do período = MD + MOD + ___.", "verso": "CIF (custos indiretos de fabricação).", "explicacao": "MD: materiais diretos; MOD: mão de obra direta."}, {"id": 2000002087, "trilha": "fiscal", "materia": "cont", "assunto": "Contabilidade pública", "tipo": "pergunta", "frente": "Quais os regimes da contabilidade pública para receitas e despesas orçamentárias?", "verso": "Receita orçamentária: pertencem ao exercício em que arrecadadas. Despesa orçamentária: ao exercício em que legalmente empenhadas.", "explicacao": "Lei 4.320/1964, art. 35. Na contabilidade patrimonial, aplica-se a competência."}, {"id": 2000002088, "trilha": "fiscal", "materia": "cont", "assunto": "Contabilidade pública", "tipo": "pergunta", "frente": "Quais os subsistemas (naturezas) de informação da contabilidade aplicada ao setor público?", "verso": "Natureza orçamentária, patrimonial e de controle.", "explicacao": "MCASP: contas classes 1 a 4 (patrimonial), 5 e 6 (orçamentária), 7 e 8 (controle)."}, {"id": 2000002089, "trilha": "fiscal", "materia": "cont", "assunto": "Contabilidade pública", "tipo": "pergunta", "frente": "Quais as demonstrações contábeis aplicadas ao setor público?", "verso": "Balanço orçamentário, financeiro, patrimonial, demonstração das variações patrimoniais, dos fluxos de caixa e das mutações do PL, além de notas explicativas.", "explicacao": "MCASP."}, {"id": 2000002090, "trilha": "fiscal", "materia": "cont", "assunto": "Contabilidade pública", "tipo": "pergunta", "frente": "O que mostra o balanço orçamentário?", "verso": "As receitas previstas e as realizadas e as despesas fixadas e as executadas.", "explicacao": "Lei 4.320/1964, art. 102."}, {"id": 2000002091, "trilha": "fiscal", "materia": "cont", "assunto": "Contabilidade pública", "tipo": "pergunta", "frente": "O que mostra o balanço financeiro?", "verso": "As receitas e despesas orçamentárias e os recebimentos e pagamentos extraorçamentários, com os saldos de caixa do exercício anterior e do seguinte.", "explicacao": "Lei 4.320/1964, art. 103."}, {"id": 2000002092, "trilha": "fiscal", "materia": "cont", "assunto": "Contabilidade pública", "tipo": "pares", "frente": "Superávit financeiro x superávit orçamentário.", "verso": "Financeiro: diferença positiva entre ativo financeiro e passivo financeiro no balanço patrimonial; é fonte para créditos adicionais. Orçamentário: receita realizada maior que a despesa executada no exercício.", "explicacao": ""}, {"id": 2000002093, "trilha": "fiscal", "materia": "cont", "assunto": "Normas", "tipo": "pergunta", "frente": "O que é o CPC?", "verso": "Comitê de Pronunciamentos Contábeis, que emite pronunciamentos convergentes com as normas internacionais (IFRS).", "explicacao": "Aprovados pelo CFC, CVM e outros reguladores."}, {"id": 2000002094, "trilha": "fiscal", "materia": "cont", "assunto": "Normas", "tipo": "pergunta", "frente": "Qual lei trouxe a convergência da contabilidade brasileira às normas internacionais?", "verso": "A Lei 11.638/2007, que alterou a Lei 6.404.", "explicacao": "Complementada pela Lei 11.941/2009."}, {"id": 2000002095, "trilha": "fiscal", "materia": "cont", "assunto": "Operações", "tipo": "pergunta", "frente": "Como se contabiliza o aumento de capital com reservas?", "verso": "D – Reservas; C – Capital social. Não altera o total do PL.", "explicacao": ""}, {"id": 2000002096, "trilha": "fiscal", "materia": "cont", "assunto": "Operações", "tipo": "pergunta", "frente": "Como se registra a venda de um imobilizado com lucro?", "verso": "D – Caixa; D – Depreciação acumulada; C – Imobilizado; C – Ganho na alienação (outras receitas).", "explicacao": "O ganho é a diferença entre o valor de venda e o valor contábil."}, {"id": 2000002097, "trilha": "fiscal", "materia": "cont", "assunto": "Operações", "tipo": "pergunta", "frente": "Como se apropria uma despesa paga antecipadamente, como seguro anual?", "verso": "Registra-se no ativo (seguros a apropriar) e apropria-se como despesa mês a mês.", "explicacao": "Regime de competência."}, {"id": 2000002098, "trilha": "fiscal", "materia": "cont", "assunto": "Operações", "tipo": "pergunta", "frente": "O que é ajuste a valor presente?", "verso": "Trazer a valor presente ativos e passivos de longo prazo (e de curto prazo quando relevante), separando os juros embutidos.", "explicacao": "CPC 12."}, {"id": 2000002099, "trilha": "fiscal", "materia": "cont", "assunto": "Operações", "tipo": "pergunta", "frente": "O que é o método da equivalência patrimonial?", "verso": "Avaliação de investimentos em coligadas e controladas pela participação proporcional no PL da investida.", "explicacao": "CPC 18. O resultado da investida afeta o resultado da investidora."}, {"id": 2000002100, "trilha": "fiscal", "materia": "cont", "assunto": "Operações", "tipo": "pergunta", "frente": "Os dividendos recebidos de controlada avaliada por equivalência são receita?", "verso": "Não. Reduzem o valor do investimento (D – Caixa; C – Investimento).", "explicacao": "A receita foi reconhecida quando a investida teve lucro."}, {"id": 2000002101, "trilha": "fiscal", "materia": "cont", "assunto": "Operações", "tipo": "pergunta", "frente": "Quando uma provisão deve ser reconhecida no passivo (CPC 25)?", "verso": "Quando há obrigação presente, saída de recursos provável e estimativa confiável do valor.", "explicacao": "Se a saída for apenas possível, divulga-se em nota (passivo contingente)."}, {"id": 2000002102, "trilha": "fiscal", "materia": "cont", "assunto": "Operações", "tipo": "pares", "frente": "Provisão x passivo contingente x ativo contingente.", "verso": "Provisão: saída provável, reconhecida no passivo. Passivo contingente: saída possível, apenas divulgada. Ativo contingente: não se reconhece; divulga-se quando a entrada for provável.", "explicacao": "CPC 25."}, {"id": 2000002103, "trilha": "fiscal", "materia": "cont", "assunto": "Operações", "tipo": "pergunta", "frente": "O que é arrendamento no CPC 06 (R2) para o arrendatário?", "verso": "Em regra, o arrendatário reconhece no ativo o direito de uso e no passivo a obrigação do arrendamento.", "explicacao": "Exceções: curto prazo e baixo valor."}, {"id": 2000002104, "trilha": "fiscal", "materia": "cont", "assunto": "Erros", "tipo": "pergunta", "frente": "O que é estorno?", "verso": "Lançamento inverso para anular um lançamento errado.", "explicacao": "Outros métodos de retificação: transferência e complementação."}, {"id": 2000002105, "trilha": "fiscal", "materia": "cont", "assunto": "Erros", "tipo": "pergunta", "frente": "Como se trata a correção de erro de exercícios anteriores?", "verso": "Retrospectivamente, ajustando os saldos de abertura (lucros ou prejuízos acumulados), sem afetar o resultado do exercício atual.", "explicacao": "CPC 23."}, {"id": 2000002106, "trilha": "fiscal", "materia": "cont", "assunto": "Tributos", "tipo": "pares", "frente": "Lucro real x presumido x Simples Nacional.", "verso": "Real: IR sobre o lucro contábil ajustado. Presumido: IR sobre percentual da receita bruta. Simples: regime unificado para micro e pequenas empresas, com alíquota sobre a receita.", "explicacao": "Obrigam o lucro real, por exemplo, receita acima de R$ 78 milhões e bancos."}, {"id": 2000002107, "trilha": "fiscal", "materia": "cont", "assunto": "Tributos", "tipo": "pergunta", "frente": "O que são PIS e Cofins não cumulativos?", "verso": "Regime em que a empresa desconta créditos sobre certos insumos e despesas; alíquotas de 1,65% e 7,6%.", "explicacao": "Aplicado em geral a empresas no lucro real. No cumulativo: 0,65% e 3%."}, {"id": 2000002108, "trilha": "fiscal", "materia": "afo", "assunto": "Instrumentos de planejamento", "tipo": "pergunta", "frente": "Quais são as leis orçamentárias previstas na CF?", "verso": "Plano Plurianual (PPA), Lei de Diretrizes Orçamentárias (LDO) e Lei Orçamentária Anual (LOA).", "explicacao": "CF, art. 165. Todas de iniciativa do Poder Executivo."}, {"id": 2000002109, "trilha": "fiscal", "materia": "afo", "assunto": "Instrumentos de planejamento", "tipo": "pergunta", "frente": "O que o PPA estabelece?", "verso": "De forma regionalizada, as diretrizes, objetivos e metas da administração pública federal para as despesas de capital e outras delas decorrentes e para as relativas aos programas de duração continuada.", "explicacao": "CF, art. 165, § 1º."}, {"id": 2000002110, "trilha": "fiscal", "materia": "afo", "assunto": "Instrumentos de planejamento", "tipo": "pergunta", "frente": "O que a LDO estabelece?", "verso": "Metas e prioridades da administração, orientações para a elaboração da LOA, alterações na legislação tributária e política das agências oficiais de fomento.", "explicacao": "CF, art. 165, § 2º. Pela LRF, traz Anexo de Metas Fiscais e de Riscos Fiscais."}, {"id": 2000002111, "trilha": "fiscal", "materia": "afo", "assunto": "Instrumentos de planejamento", "tipo": "pergunta", "frente": "Quais orçamentos compõem a LOA?", "verso": "Orçamento fiscal, orçamento de investimento das empresas estatais e orçamento da seguridade social.", "explicacao": "CF, art. 165, § 5º."}, {"id": 2000002112, "trilha": "fiscal", "materia": "afo", "assunto": "Instrumentos de planejamento", "tipo": "pergunta", "frente": "Quais os prazos de envio dos projetos de PPA, LDO e LOA na União (ADCT)?", "verso": "PPA: até 31 de agosto do primeiro ano do mandato. LDO: até 15 de abril. LOA: até 31 de agosto.", "explicacao": "ADCT, art. 35, § 2º."}, {"id": 2000002113, "trilha": "fiscal", "materia": "afo", "assunto": "Instrumentos de planejamento", "tipo": "pergunta", "frente": "Até quando o Congresso deve devolver o projeto da LDO para sanção?", "verso": "Até o encerramento do primeiro período da sessão legislativa (17 de julho). A sessão não é interrompida sem a aprovação da LDO.", "explicacao": "ADCT, art. 35, § 2º, II; CF, art. 57, § 2º."}, {"id": 2000002114, "trilha": "fiscal", "materia": "afo", "assunto": "Instrumentos de planejamento", "tipo": "pergunta", "frente": "Quem examina e emite parecer sobre os projetos de leis orçamentárias?", "verso": "A Comissão Mista Permanente de Senadores e Deputados (CMO).", "explicacao": "CF, art. 166, § 1º."}, {"id": 2000002115, "trilha": "fiscal", "materia": "afo", "assunto": "Instrumentos de planejamento", "tipo": "pergunta", "frente": "Até quando o Presidente pode propor modificações nos projetos orçamentários enviados?", "verso": "Enquanto não iniciada a votação, na CMO, da parte cuja alteração é proposta.", "explicacao": "CF, art. 166, § 5º."}, {"id": 2000002116, "trilha": "fiscal", "materia": "afo", "assunto": "Emendas", "tipo": "pergunta", "frente": "Quais condições as emendas ao projeto da LOA devem cumprir?", "verso": "Ser compatíveis com o PPA e a LDO e indicar recursos, admitidos apenas os de anulação de despesa, excluídas dotações para pessoal e encargos, serviço da dívida e transferências constitucionais.", "explicacao": "CF, art. 166, § 3º."}, {"id": 2000002117, "trilha": "fiscal", "materia": "afo", "assunto": "Emendas", "tipo": "pergunta", "frente": "Qual o percentual das emendas individuais impositivas?", "verso": "2% da receita corrente líquida do exercício anterior, sendo metade destinada a ações e serviços públicos de saúde.", "explicacao": "CF, art. 166, § 9º (EC 126/2022)."}, {"id": 2000002118, "trilha": "fiscal", "materia": "afo", "assunto": "Princípios", "tipo": "pergunta", "frente": "O que diz o princípio da anualidade?", "verso": "O orçamento vale por um exercício financeiro, que coincide com o ano civil.", "explicacao": "Lei 4.320/1964, art. 34."}, {"id": 2000002119, "trilha": "fiscal", "materia": "afo", "assunto": "Princípios", "tipo": "pergunta", "frente": "O que diz o princípio da exclusividade?", "verso": "A LOA não conterá dispositivo estranho à previsão da receita e à fixação da despesa.", "explicacao": "CF, art. 165, § 8º. Exceções: créditos suplementares e operações de crédito, inclusive por ARO."}, {"id": 2000002120, "trilha": "fiscal", "materia": "afo", "assunto": "Princípios", "tipo": "pergunta", "frente": "O que diz o princípio da não afetação (não vinculação) de receitas?", "verso": "É vedada a vinculação de receita de impostos a órgão, fundo ou despesa, ressalvadas as exceções constitucionais.", "explicacao": "CF, art. 167, IV. Exceções: saúde, educação, repartição constitucional, administração tributária, garantias de ARO."}, {"id": 2000002121, "trilha": "fiscal", "materia": "afo", "assunto": "Princípios", "tipo": "pares", "frente": "Princípio da universalidade x unidade.", "verso": "Universalidade: todas as receitas e despesas devem constar do orçamento. Unidade (totalidade): um só orçamento para cada ente, ainda que composto de várias peças (fiscal, seguridade e investimento).", "explicacao": "Lei 4.320/1964, arts. 2º, 3º e 4º."}, {"id": 2000002122, "trilha": "fiscal", "materia": "afo", "assunto": "Princípios", "tipo": "pergunta", "frente": "O que diz o princípio do orçamento bruto?", "verso": "Receitas e despesas constarão pelos totais, vedadas quaisquer deduções.", "explicacao": "Lei 4.320/1964, art. 6º."}, {"id": 2000002123, "trilha": "fiscal", "materia": "afo", "assunto": "Princípios", "tipo": "pergunta", "frente": "O que diz o princípio da especificação (discriminação)?", "verso": "Receitas e despesas devem ser discriminadas de modo a mostrar origem e aplicação, vedadas dotações globais.", "explicacao": "Lei 4.320/1964, arts. 5º e 15."}, {"id": 2000002124, "trilha": "fiscal", "materia": "afo", "assunto": "Princípios", "tipo": "pergunta", "frente": "O que diz o princípio do equilíbrio?", "verso": "A despesa fixada não deve ser superior à receita prevista.", "explicacao": "Regra de ouro: operações de crédito não podem superar despesas de capital (CF, art. 167, III)."}, {"id": 2000002125, "trilha": "fiscal", "materia": "afo", "assunto": "Princípios", "tipo": "pergunta", "frente": "O que é a regra de ouro?", "verso": "Vedação à realização de operações de crédito que excedam o montante das despesas de capital, salvo créditos suplementares ou especiais aprovados por maioria absoluta do Legislativo.", "explicacao": "CF, art. 167, III."}, {"id": 2000002126, "trilha": "fiscal", "materia": "afo", "assunto": "Princípios", "tipo": "pergunta", "frente": "O que diz o princípio da legalidade orçamentária?", "verso": "A arrecadação e a realização de despesas dependem de autorização legislativa (leis orçamentárias).", "explicacao": "CF, art. 167, I e II."}, {"id": 2000002127, "trilha": "fiscal", "materia": "afo", "assunto": "Receita", "tipo": "pares", "frente": "Receita orçamentária x extraorçamentária.", "verso": "Orçamentária: disponibilidade que pertence ao ente e pode financiar despesas (tributos, transferências, operações de crédito). Extraorçamentária: valores transitórios, que serão devolvidos (cauções, depósitos, retenções, ARO).", "explicacao": "ARO é extraorçamentária."}, {"id": 2000002128, "trilha": "fiscal", "materia": "afo", "assunto": "Receita", "tipo": "pares", "frente": "Receitas correntes x de capital.", "verso": "Correntes: tributária, de contribuições, patrimonial, agropecuária, industrial, de serviços, transferências correntes e outras. Capital: operações de crédito, alienação de bens, amortização de empréstimos, transferências de capital e outras.", "explicacao": "Lei 4.320/1964, art. 11."}, {"id": 2000002129, "trilha": "fiscal", "materia": "afo", "assunto": "Receita", "tipo": "pergunta", "frente": "Quais são os estágios da receita orçamentária?", "verso": "Previsão, lançamento, arrecadação e recolhimento.", "explicacao": "Nem toda receita passa pelo lançamento."}, {"id": 2000002130, "trilha": "fiscal", "materia": "afo", "assunto": "Receita", "tipo": "pares", "frente": "Arrecadação x recolhimento.", "verso": "Arrecadação: entrega dos recursos pelos contribuintes aos agentes arrecadadores (bancos). Recolhimento: transferência dos agentes arrecadadores para a conta única do Tesouro.", "explicacao": ""}, {"id": 2000002131, "trilha": "fiscal", "materia": "afo", "assunto": "Receita", "tipo": "pergunta", "frente": "O que é dívida ativa?", "verso": "Créditos da Fazenda Pública, tributários ou não, exigíveis pelo vencimento do prazo, inscritos após apuração de liquidez e certeza.", "explicacao": "Lei 4.320/1964, art. 39. A cobrança da dívida ativa gera receita orçamentária corrente."}, {"id": 2000002132, "trilha": "fiscal", "materia": "afo", "assunto": "Receita", "tipo": "pergunta", "frente": "O que é a receita corrente líquida (RCL)?", "verso": "Somatório das receitas correntes, deduzidas transferências constitucionais e legais a outros entes e as contribuições para a seguridade e previdência dos servidores, entre outras.", "explicacao": "LRF, art. 2º, IV. Base de cálculo dos limites da LRF."}, {"id": 2000002133, "trilha": "fiscal", "materia": "afo", "assunto": "Receita", "tipo": "pergunta", "frente": "Quais os requisitos para concessão de renúncia de receita na LRF?", "verso": "Estimativa do impacto orçamentário-financeiro no exercício e nos dois seguintes, atender a LDO e: demonstrar que foi considerada na estimativa de receita ou adotar medidas de compensação (aumento de receita).", "explicacao": "LRF, art. 14."}, {"id": 2000002134, "trilha": "fiscal", "materia": "afo", "assunto": "Despesa", "tipo": "pares", "frente": "Despesas correntes x de capital.", "verso": "Correntes: não contribuem diretamente para formar ou adquirir bem de capital (pessoal, juros, material de consumo). Capital: contribuem (investimentos, inversões financeiras, amortização da dívida).", "explicacao": "Lei 4.320/1964, arts. 12 e 13."}, {"id": 2000002135, "trilha": "fiscal", "materia": "afo", "assunto": "Despesa", "tipo": "pares", "frente": "Investimentos x inversões financeiras.", "verso": "Investimentos: planejamento e execução de obras, compra de equipamentos e material permanente. Inversões financeiras: aquisição de imóveis ou bens de capital já em uso, aquisição de títulos e constituição de capital de empresas.", "explicacao": ""}, {"id": 2000002136, "trilha": "fiscal", "materia": "afo", "assunto": "Despesa", "tipo": "pergunta", "frente": "Quais os estágios da despesa orçamentária pela Lei 4.320?", "verso": "Empenho, liquidação e pagamento.", "explicacao": "Antes, na fase de planejamento: fixação, descentralização e programação."}, {"id": 2000002137, "trilha": "fiscal", "materia": "afo", "assunto": "Despesa", "tipo": "pergunta", "frente": "O que é empenho?", "verso": "Ato da autoridade que cria para o Estado obrigação de pagamento, pendente ou não de implemento de condição.", "explicacao": "Lei 4.320/1964, art. 58. É vedada despesa sem prévio empenho (art. 60)."}, {"id": 2000002138, "trilha": "fiscal", "materia": "afo", "assunto": "Despesa", "tipo": "pares", "frente": "Empenho ordinário x estimativo x global.", "verso": "Ordinário: valor exato, pago de uma vez. Estimativo: quando não se pode determinar o valor (água, energia). Global: despesas contratuais de valor conhecido, pagas parceladamente (aluguel).", "explicacao": ""}, {"id": 2000002139, "trilha": "fiscal", "materia": "afo", "assunto": "Despesa", "tipo": "pergunta", "frente": "O que é liquidação da despesa?", "verso": "Verificação do direito adquirido pelo credor, com base nos títulos e documentos comprobatórios do crédito (comprovação da entrega do bem ou serviço).", "explicacao": "Lei 4.320/1964, art. 63."}, {"id": 2000002140, "trilha": "fiscal", "materia": "afo", "assunto": "Despesa", "tipo": "pergunta", "frente": "Qual documento autoriza o pagamento da despesa?", "verso": "A ordem de pagamento, só exarada em documentos processados pelos serviços de contabilidade.", "explicacao": "Lei 4.320/1964, art. 64."}, {"id": 2000002141, "trilha": "fiscal", "materia": "afo", "assunto": "Despesa", "tipo": "pergunta", "frente": "O que são despesas de exercícios anteriores?", "verso": "Despesas de exercícios encerrados, para as quais havia crédito próprio mas que não foram processadas na época, restos a pagar com prescrição interrompida e compromissos reconhecidos após o encerramento.", "explicacao": "Lei 4.320/1964, art. 37. Pagas à conta de dotação específica do orçamento atual."}, {"id": 2000002142, "trilha": "fiscal", "materia": "afo", "assunto": "Despesa", "tipo": "pergunta", "frente": "O que é o regime de adiantamento (suprimento de fundos)?", "verso": "Entrega de numerário a servidor, sempre precedida de empenho, para despesas que não possam se subordinar ao processo normal de aplicação.", "explicacao": "Lei 4.320/1964, art. 68. Não pode ser concedido a servidor em alcance."}, {"id": 2000002143, "trilha": "fiscal", "materia": "afo", "assunto": "Despesa", "tipo": "pergunta", "frente": "Como se estrutura a classificação por natureza da despesa?", "verso": "Categoria econômica, grupo de natureza da despesa, modalidade de aplicação e elemento de despesa (ex.: 3.1.90.11).", "explicacao": "3: corrente; 4: capital."}, {"id": 2000002144, "trilha": "fiscal", "materia": "afo", "assunto": "Despesa", "tipo": "pergunta", "frente": "Quais são os grupos de natureza da despesa (GND)?", "verso": "1 Pessoal e encargos; 2 Juros e encargos da dívida; 3 Outras despesas correntes; 4 Investimentos; 5 Inversões financeiras; 6 Amortização da dívida.", "explicacao": ""}, {"id": 2000002145, "trilha": "fiscal", "materia": "afo", "assunto": "Despesa", "tipo": "pares", "frente": "Classificação funcional x programática.", "verso": "Funcional: em que área o governo gasta (função e subfunção, como saúde e atenção básica). Programática: para que gasta (programas e ações: projetos, atividades e operações especiais).", "explicacao": "Portaria MOG 42/1999."}, {"id": 2000002146, "trilha": "fiscal", "materia": "afo", "assunto": "Despesa", "tipo": "pares", "frente": "Projeto x atividade x operação especial.", "verso": "Projeto: ações limitadas no tempo que expandem ou aperfeiçoam a ação do governo (construir uma escola). Atividade: ações contínuas e permanentes (manter a escola). Operação especial: não geram produto (pagamento da dívida, transferências).", "explicacao": ""}, {"id": 2000002147, "trilha": "fiscal", "materia": "afo", "assunto": "Restos a pagar", "tipo": "pergunta", "frente": "O que são restos a pagar?", "verso": "Despesas empenhadas e não pagas até 31 de dezembro.", "explicacao": "Lei 4.320/1964, art. 36."}, {"id": 2000002148, "trilha": "fiscal", "materia": "afo", "assunto": "Restos a pagar", "tipo": "pares", "frente": "Restos a pagar processados x não processados.", "verso": "Processados: despesas já liquidadas. Não processados: empenhadas, mas não liquidadas.", "explicacao": ""}, {"id": 2000002149, "trilha": "fiscal", "materia": "afo", "assunto": "Restos a pagar", "tipo": "pergunta", "frente": "O que veda o art. 42 da LRF?", "verso": "Ao titular de Poder ou órgão, nos dois últimos quadrimestres do mandato, contrair obrigação de despesa que não possa ser cumprida integralmente dentro dele, ou que tenha parcelas a pagar no exercício seguinte sem disponibilidade de caixa.", "explicacao": "LRF, art. 42."}, {"id": 2000002150, "trilha": "fiscal", "materia": "afo", "assunto": "Créditos adicionais", "tipo": "pergunta", "frente": "Quais as espécies de créditos adicionais?", "verso": "Suplementares, especiais e extraordinários.", "explicacao": "Lei 4.320/1964, art. 41."}, {"id": 2000002151, "trilha": "fiscal", "materia": "afo", "assunto": "Créditos adicionais", "tipo": "pares", "frente": "Crédito suplementar x especial x extraordinário.", "verso": "Suplementar: reforça dotação existente. Especial: para despesa sem dotação específica. Extraordinário: despesas urgentes e imprevisíveis (guerra, comoção interna ou calamidade).", "explicacao": "Lei 4.320/1964, art. 41."}, {"id": 2000002152, "trilha": "fiscal", "materia": "afo", "assunto": "Créditos adicionais", "tipo": "pergunta", "frente": "Como são abertos os créditos suplementares e especiais?", "verso": "Autorizados por lei e abertos por decreto do Executivo, com indicação dos recursos.", "explicacao": "Lei 4.320/1964, art. 42. A LOA pode trazer autorização prévia para suplementares."}, {"id": 2000002153, "trilha": "fiscal", "materia": "afo", "assunto": "Créditos adicionais", "tipo": "pergunta", "frente": "Como é aberto o crédito extraordinário na União?", "verso": "Por medida provisória.", "explicacao": "CF, art. 167, § 3º, e art. 62."}, {"id": 2000002154, "trilha": "fiscal", "materia": "afo", "assunto": "Créditos adicionais", "tipo": "pergunta", "frente": "Quais as fontes de recursos para créditos suplementares e especiais?", "verso": "Superávit financeiro do exercício anterior, excesso de arrecadação, anulação parcial ou total de dotações e produto de operações de crédito autorizadas.", "explicacao": "Lei 4.320/1964, art. 43. Também a reserva de contingência."}, {"id": 2000002155, "trilha": "fiscal", "materia": "afo", "assunto": "Créditos adicionais", "tipo": "pergunta", "frente": "Qual a vigência dos créditos especiais e extraordinários?", "verso": "No exercício em que forem autorizados, salvo se o ato de autorização for promulgado nos últimos 4 meses, quando podem ser reabertos no exercício seguinte pelo saldo.", "explicacao": "CF, art. 167, § 2º."}, {"id": 2000002156, "trilha": "fiscal", "materia": "afo", "assunto": "Créditos adicionais", "tipo": "pergunta", "frente": "O crédito suplementar pode ser reaberto no exercício seguinte?", "verso": "Não. Só os especiais e extraordinários podem ser reabertos.", "explicacao": ""}, {"id": 2000002157, "trilha": "fiscal", "materia": "afo", "assunto": "Execução", "tipo": "pergunta", "frente": "O que é a programação financeira e o cronograma de desembolso?", "verso": "Até 30 dias após a publicação do orçamento, o Executivo estabelece a programação financeira e o cronograma mensal de desembolso.", "explicacao": "LRF, art. 8º."}, {"id": 2000002158, "trilha": "fiscal", "materia": "afo", "assunto": "Execução", "tipo": "pergunta", "frente": "O que é limitação de empenho (contingenciamento)?", "verso": "Se, ao fim de um bimestre, a receita não comportar as metas de resultado, os Poderes limitam empenho e movimentação financeira nos 30 dias seguintes.", "explicacao": "LRF, art. 9º. Não atinge despesas obrigatórias constitucionais e legais."}, {"id": 2000002159, "trilha": "fiscal", "materia": "afo", "assunto": "Execução", "tipo": "pares", "frente": "Descentralização de crédito x de recurso financeiro.", "verso": "Crédito (orçamentária): provisão (entre unidades do mesmo órgão) e destaque (entre órgãos diferentes). Financeira: cota (do Tesouro ao órgão setorial), repasse (entre órgãos diferentes) e sub-repasse (dentro do mesmo órgão).", "explicacao": "Mnemônico: provisão e sub-repasse são internos; destaque e repasse, externos."}, {"id": 2000002160, "trilha": "fiscal", "materia": "afo", "assunto": "Execução", "tipo": "pergunta", "frente": "O que é a conta única do Tesouro Nacional?", "verso": "Conta mantida no Banco Central onde ficam as disponibilidades financeiras da União.", "explicacao": "CF, art. 164, § 3º."}, {"id": 2000002161, "trilha": "fiscal", "materia": "afo", "assunto": "LRF", "tipo": "pergunta", "frente": "Qual o objetivo da Lei de Responsabilidade Fiscal?", "verso": "Estabelecer normas de finanças públicas voltadas à responsabilidade na gestão fiscal, com ação planejada e transparente, prevenindo riscos e corrigindo desvios.", "explicacao": "LC 101/2000, art. 1º."}, {"id": 2000002162, "trilha": "fiscal", "materia": "afo", "assunto": "LRF", "tipo": "pergunta", "frente": "Quais os limites de despesa com pessoal na LRF?", "verso": "União: 50% da RCL. Estados e municípios: 60% da RCL.", "explicacao": "LRF, art. 19."}, {"id": 2000002163, "trilha": "fiscal", "materia": "afo", "assunto": "LRF", "tipo": "pergunta", "frente": "Como se divide o limite de pessoal dos estados?", "verso": "Legislativo (com TCE): 3%; Judiciário: 6%; MP: 2%; Executivo: 49%.", "explicacao": "LRF, art. 20, II."}, {"id": 2000002164, "trilha": "fiscal", "materia": "afo", "assunto": "LRF", "tipo": "pergunta", "frente": "Como se divide o limite de pessoal dos municípios?", "verso": "Legislativo (com TCM, se houver): 6%; Executivo: 54%.", "explicacao": "LRF, art. 20, III."}, {"id": 2000002165, "trilha": "fiscal", "materia": "afo", "assunto": "LRF", "tipo": "pergunta", "frente": "O que acontece ao atingir 95% do limite de pessoal (limite prudencial)?", "verso": "Ficam vedados concessão de vantagens e reajustes (salvo revisão geral), criação de cargos, alteração de carreira, provimento (salvo reposição em educação, saúde e segurança) e horas extras, com exceções.", "explicacao": "LRF, art. 22, parágrafo único."}, {"id": 2000002166, "trilha": "fiscal", "materia": "afo", "assunto": "LRF", "tipo": "pergunta", "frente": "Qual o prazo para eliminar o excesso de despesa com pessoal?", "verso": "Nos dois quadrimestres seguintes, sendo pelo menos 1/3 no primeiro.", "explicacao": "LRF, art. 23."}, {"id": 2000002167, "trilha": "fiscal", "materia": "afo", "assunto": "LRF", "tipo": "pergunta", "frente": "Qual o limite de alerta do Tribunal de Contas para despesa com pessoal?", "verso": "90% do limite.", "explicacao": "LRF, art. 59, § 1º, II."}, {"id": 2000002168, "trilha": "fiscal", "materia": "afo", "assunto": "LRF", "tipo": "pergunta", "frente": "O que é o Relatório Resumido da Execução Orçamentária (RREO)?", "verso": "Relatório publicado até 30 dias após o encerramento de cada bimestre, pelo Poder Executivo.", "explicacao": "LRF, arts. 52 e 53; CF, art. 165, § 3º."}, {"id": 2000002169, "trilha": "fiscal", "materia": "afo", "assunto": "LRF", "tipo": "pergunta", "frente": "O que é o Relatório de Gestão Fiscal (RGF)?", "verso": "Relatório emitido ao fim de cada quadrimestre pelos titulares dos Poderes e órgãos, com despesa de pessoal, dívida, garantias e operações de crédito.", "explicacao": "LRF, arts. 54 e 55. Publicado até 30 dias após o quadrimestre."}, {"id": 2000002170, "trilha": "fiscal", "materia": "afo", "assunto": "LRF", "tipo": "pergunta", "frente": "O que é despesa obrigatória de caráter continuado?", "verso": "Despesa corrente derivada de lei, MP ou ato que fixe obrigação legal de execução por período superior a dois exercícios.", "explicacao": "LRF, art. 17."}, {"id": 2000002171, "trilha": "fiscal", "materia": "afo", "assunto": "LRF", "tipo": "pergunta", "frente": "O que é a reserva de contingência?", "verso": "Dotação na LOA, com forma e montante definidos na LDO, para passivos contingentes, riscos e eventos fiscais imprevistos.", "explicacao": "LRF, art. 5º, III."}, {"id": 2000002172, "trilha": "fiscal", "materia": "afo", "assunto": "LRF", "tipo": "pergunta", "frente": "O que é operação de crédito por antecipação de receita (ARO)?", "verso": "Empréstimo de curto prazo para cobrir insuficiência de caixa durante o exercício.", "explicacao": "LRF, art. 38. Deve ser quitada até 10 de dezembro e é proibida no último ano de mandato."}, {"id": 2000002173, "trilha": "fiscal", "materia": "afo", "assunto": "LRF", "tipo": "pergunta", "frente": "É permitida operação de crédito entre entes da Federação?", "verso": "É vedada, inclusive refinanciamento ou postergação de dívida contraída anteriormente, salvo exceções (instituição financeira estatal, nas condições da lei).", "explicacao": "LRF, art. 35."}, {"id": 2000002174, "trilha": "fiscal", "materia": "afo", "assunto": "LRF", "tipo": "pergunta", "frente": "Quem fixa os limites globais da dívida consolidada de estados e municípios?", "verso": "O Senado Federal, por resolução.", "explicacao": "CF, art. 52, VI; Resolução do Senado 40/2001 (2 vezes a RCL para estados e 1,2 para municípios)."}, {"id": 2000002175, "trilha": "fiscal", "materia": "afo", "assunto": "LRF", "tipo": "pergunta", "frente": "O que é resultado primário?", "verso": "Diferença entre receitas e despesas não financeiras (exclui juros e operações financeiras).", "explicacao": "Mostra se o governo gasta mais do que arrecada sem considerar a dívida."}, {"id": 2000002176, "trilha": "fiscal", "materia": "afo", "assunto": "LRF", "tipo": "pares", "frente": "Resultado primário x nominal.", "verso": "Primário: exclui os juros. Nominal: inclui os juros da dívida; mostra a necessidade de financiamento do setor público.", "explicacao": ""}, {"id": 2000002177, "trilha": "fiscal", "materia": "afo", "assunto": "LRF", "tipo": "pergunta", "frente": "O que é transferência voluntária?", "verso": "Entrega de recursos a outro ente, a título de cooperação, auxílio ou assistência financeira, que não decorra de determinação constitucional, legal ou do SUS.", "explicacao": "LRF, art. 25."}, {"id": 2000002178, "trilha": "fiscal", "materia": "afo", "assunto": "Regime fiscal", "tipo": "pergunta", "frente": "O que é o Regime Fiscal Sustentável (arcabouço fiscal)?", "verso": "Regra da LC 200/2023 que limita o crescimento da despesa primária da União a 70% do crescimento da receita, entre 0,6% e 2,5% reais ao ano, com metas de resultado primário.", "explicacao": "Substituiu o teto de gastos da EC 95/2016."}, {"id": 2000002179, "trilha": "fiscal", "materia": "afo", "assunto": "Ciclo orçamentário", "tipo": "pergunta", "frente": "Quais as fases do ciclo orçamentário?", "verso": "Elaboração (proposta), discussão, votação e aprovação, execução e controle e avaliação.", "explicacao": "O ciclo é mais longo que o exercício financeiro."}, {"id": 2000002180, "trilha": "fiscal", "materia": "afo", "assunto": "Tipos de orçamento", "tipo": "pares", "frente": "Orçamento tradicional x orçamento-programa.", "verso": "Tradicional: foco no objeto do gasto (o que se compra), controle contábil. Orçamento-programa: foco nos objetivos, metas e resultados, ligado ao planejamento.", "explicacao": "O Brasil adota o orçamento-programa."}, {"id": 2000002181, "trilha": "fiscal", "materia": "afo", "assunto": "Tipos de orçamento", "tipo": "pergunta", "frente": "O que é orçamento base zero?", "verso": "Técnica em que cada despesa precisa ser justificada a cada ano, como se partisse do zero, sem considerar o histórico.", "explicacao": ""}, {"id": 2000002182, "trilha": "fiscal", "materia": "afo", "assunto": "Tipos de orçamento", "tipo": "pergunta", "frente": "O que é orçamento participativo?", "verso": "Participação direta da população na definição de parte das prioridades de investimento.", "explicacao": "Porto Alegre (1989) é a experiência mais conhecida."}, {"id": 2000002183, "trilha": "fiscal", "materia": "afo", "assunto": "Controle", "tipo": "pergunta", "frente": "Quem exerce o controle externo da execução orçamentária na União?", "verso": "O Congresso Nacional, com auxílio do Tribunal de Contas da União.", "explicacao": "CF, art. 71."}, {"id": 2000002184, "trilha": "fiscal", "materia": "afo", "assunto": "Controle", "tipo": "pergunta", "frente": "Qual a natureza das contas anuais do Presidente analisadas pelo TCU?", "verso": "O TCU emite parecer prévio em 60 dias; o julgamento cabe ao Congresso Nacional.", "explicacao": "CF, arts. 49, IX, e 71, I."}, {"id": 2000002185, "trilha": "fiscal", "materia": "afo", "assunto": "Vedações", "tipo": "pergunta", "frente": "É possível iniciar programa ou projeto não incluído na LOA?", "verso": "Não.", "explicacao": "CF, art. 167, I."}, {"id": 2000002186, "trilha": "fiscal", "materia": "afo", "assunto": "Vedações", "tipo": "pergunta", "frente": "É permitida a transposição, remanejamento ou transferência de recursos sem autorização legislativa?", "verso": "Não, salvo no âmbito de atividades de ciência, tecnologia e inovação, por ato do Executivo, nos termos da CF.", "explicacao": "CF, art. 167, VI e § 5º."}, {"id": 2000002187, "trilha": "fiscal", "materia": "afo", "assunto": "Vedações", "tipo": "pergunta", "frente": "Investimento que ultrapasse um exercício pode começar sem estar no PPA?", "verso": "Não, salvo se lei autorizar sua inclusão, sob pena de crime de responsabilidade.", "explicacao": "CF, art. 167, § 1º."}, {"id": 2000002188, "trilha": "fiscal", "materia": "afo", "assunto": "Repasses", "tipo": "pergunta", "frente": "Até que dia são repassados os duodécimos aos Poderes Legislativo e Judiciário, MP e Defensoria?", "verso": "Até o dia 20 de cada mês.", "explicacao": "CF, art. 168."}, {"id": 2000002189, "trilha": "fiscal", "materia": "afo", "assunto": "Fundos", "tipo": "pergunta", "frente": "O que são fundos especiais?", "verso": "Produto de receitas especificadas que, por lei, se vinculam à realização de determinados objetivos ou serviços.", "explicacao": "Lei 4.320/1964, art. 71. Sua instituição depende de lei."}, {"id": 2000002190, "trilha": "fiscal", "materia": "aud", "assunto": "Conceitos", "tipo": "pergunta", "frente": "Qual o objetivo da auditoria das demonstrações contábeis?", "verso": "Aumentar o grau de confiança dos usuários, por meio da opinião do auditor sobre se as demonstrações estão apresentadas, em todos os aspectos relevantes, de acordo com a estrutura de relatório financeiro aplicável.", "explicacao": "NBC TA 200."}, {"id": 2000002191, "trilha": "fiscal", "materia": "aud", "assunto": "Conceitos", "tipo": "pares", "frente": "Auditoria interna x externa (independente).", "verso": "Interna: feita por funcionários da própria entidade, foco em controles e processos, reporta à administração. Externa: feita por auditor independente, emite opinião sobre as demonstrações para usuários externos.", "explicacao": "A externa exige independência em relação à entidade."}, {"id": 2000002192, "trilha": "fiscal", "materia": "aud", "assunto": "Conceitos", "tipo": "pergunta", "frente": "O auditor garante que as demonstrações estão livres de erros?", "verso": "Não. Ele obtém segurança razoável, que é um nível alto, mas não absoluto.", "explicacao": "NBC TA 200. Limitações inerentes impedem segurança absoluta."}, {"id": 2000002193, "trilha": "fiscal", "materia": "aud", "assunto": "Conceitos", "tipo": "pergunta", "frente": "O que é ceticismo profissional?", "verso": "Postura que inclui mente questionadora, alerta a condições que indiquem possível distorção por erro ou fraude, e avaliação crítica das evidências.", "explicacao": "NBC TA 200."}, {"id": 2000002194, "trilha": "fiscal", "materia": "aud", "assunto": "Conceitos", "tipo": "pergunta", "frente": "O que é julgamento profissional em auditoria?", "verso": "Aplicação do treinamento, conhecimento e experiência relevantes para tomar decisões informadas sobre as ações apropriadas.", "explicacao": "NBC TA 200."}, {"id": 2000002195, "trilha": "fiscal", "materia": "aud", "assunto": "Conceitos", "tipo": "pares", "frente": "Erro x fraude.", "verso": "Erro: distorção não intencional. Fraude: ato intencional para obter vantagem injusta ou ilegal, envolvendo engano.", "explicacao": "NBC TA 240. O fator distintivo é a intenção."}, {"id": 2000002196, "trilha": "fiscal", "materia": "aud", "assunto": "Conceitos", "tipo": "pergunta", "frente": "Quais os dois tipos de fraude relevantes para o auditor?", "verso": "Distorções decorrentes de informações contábeis fraudulentas e de apropriação indébita de ativos.", "explicacao": "NBC TA 240."}, {"id": 2000002197, "trilha": "fiscal", "materia": "aud", "assunto": "Conceitos", "tipo": "pergunta", "frente": "Quem tem a responsabilidade principal pela prevenção e detecção de fraudes?", "verso": "Os responsáveis pela governança e a administração da entidade.", "explicacao": "NBC TA 240."}, {"id": 2000002198, "trilha": "fiscal", "materia": "aud", "assunto": "Conceitos", "tipo": "pergunta", "frente": "O que é o triângulo da fraude?", "verso": "Incentivo ou pressão, oportunidade e racionalização (atitude).", "explicacao": "Donald Cressey."}, {"id": 2000002199, "trilha": "fiscal", "materia": "aud", "assunto": "Risco de auditoria", "tipo": "lacuna", "frente": "Risco de auditoria = risco de distorção relevante × risco de ___.", "verso": "Detecção.", "explicacao": "O risco de distorção relevante combina risco inerente e risco de controle."}, {"id": 2000002200, "trilha": "fiscal", "materia": "aud", "assunto": "Risco de auditoria", "tipo": "pares", "frente": "Risco inerente x risco de controle x risco de detecção.", "verso": "Inerente: suscetibilidade de uma afirmação a distorção antes de considerar os controles. Controle: risco de que o controle interno não previna ou detecte a distorção. Detecção: risco de que os procedimentos do auditor não detectem a distorção.", "explicacao": "Só o risco de detecção é controlado pelo auditor."}, {"id": 2000002201, "trilha": "fiscal", "materia": "aud", "assunto": "Risco de auditoria", "tipo": "pergunta", "frente": "Qual a relação entre o risco de distorção relevante e o risco de detecção aceitável?", "verso": "Inversa: quanto maior o risco de distorção relevante avaliado, menor o risco de detecção aceitável, e mais evidência o auditor precisa obter.", "explicacao": ""}, {"id": 2000002202, "trilha": "fiscal", "materia": "aud", "assunto": "Materialidade", "tipo": "pergunta", "frente": "O que é materialidade (relevância) em auditoria?", "verso": "Distorções são relevantes se, individualmente ou em conjunto, puderem influenciar as decisões econômicas dos usuários tomadas com base nas demonstrações.", "explicacao": "NBC TA 320."}, {"id": 2000002203, "trilha": "fiscal", "materia": "aud", "assunto": "Materialidade", "tipo": "pergunta", "frente": "O que é materialidade para execução da auditoria?", "verso": "Valor fixado abaixo da materialidade global, para reduzir a um nível baixo a probabilidade de que distorções não corrigidas e não detectadas excedam a materialidade global.", "explicacao": "NBC TA 320."}, {"id": 2000002204, "trilha": "fiscal", "materia": "aud", "assunto": "Materialidade", "tipo": "pergunta", "frente": "Quais referenciais costumam ser usados para calcular a materialidade?", "verso": "Lucro antes dos impostos, receita total, ativo total, patrimônio líquido ou despesas totais, aplicando-se um percentual.", "explicacao": "A escolha depende das circunstâncias da entidade."}, {"id": 2000002205, "trilha": "fiscal", "materia": "aud", "assunto": "Planejamento", "tipo": "pergunta", "frente": "O que é a estratégia global de auditoria?", "verso": "Define o alcance, a época e a direção da auditoria e orienta o plano de auditoria.", "explicacao": "NBC TA 300."}, {"id": 2000002206, "trilha": "fiscal", "materia": "aud", "assunto": "Planejamento", "tipo": "pergunta", "frente": "O planejamento é uma fase isolada da auditoria?", "verso": "Não. É um processo contínuo e iterativo durante todo o trabalho.", "explicacao": "NBC TA 300."}, {"id": 2000002207, "trilha": "fiscal", "materia": "aud", "assunto": "Planejamento", "tipo": "pergunta", "frente": "O que é a carta de contratação (termos do trabalho)?", "verso": "Documento que formaliza o objetivo e alcance da auditoria, as responsabilidades do auditor e da administração e a forma dos relatórios.", "explicacao": "NBC TA 210."}, {"id": 2000002208, "trilha": "fiscal", "materia": "aud", "assunto": "Afirmações", "tipo": "pergunta", "frente": "Quais são as afirmações sobre classes de transações e eventos?", "verso": "Ocorrência, integralidade, exatidão, corte (competência), classificação e apresentação.", "explicacao": "NBC TA 315."}, {"id": 2000002209, "trilha": "fiscal", "materia": "aud", "assunto": "Afirmações", "tipo": "pergunta", "frente": "Quais são as afirmações sobre saldos contábeis no fim do período?", "verso": "Existência, direitos e obrigações, integralidade, exatidão, avaliação e alocação, classificação e apresentação.", "explicacao": "NBC TA 315."}, {"id": 2000002210, "trilha": "fiscal", "materia": "aud", "assunto": "Afirmações", "tipo": "pares", "frente": "Teste de existência x teste de integralidade.", "verso": "Existência (superavaliação): parte do registro contábil para o item físico ou documento. Integralidade (subavaliação): parte do documento ou item físico para o registro contábil.", "explicacao": "Direção do teste é muito cobrada."}, {"id": 2000002211, "trilha": "fiscal", "materia": "aud", "assunto": "Afirmações", "tipo": "pergunta", "frente": "Qual afirmação é testada principalmente na circularização de clientes?", "verso": "Existência (e direitos) das contas a receber.", "explicacao": ""}, {"id": 2000002212, "trilha": "fiscal", "materia": "aud", "assunto": "Afirmações", "tipo": "pergunta", "frente": "Qual afirmação é testada pela busca de passivos não registrados?", "verso": "Integralidade.", "explicacao": "Exame de pagamentos após a data do balanço."}, {"id": 2000002213, "trilha": "fiscal", "materia": "aud", "assunto": "Evidência", "tipo": "pergunta", "frente": "Quais as qualidades exigidas da evidência de auditoria?", "verso": "Suficiência (quantidade) e adequação (qualidade: relevância e confiabilidade).", "explicacao": "NBC TA 500."}, {"id": 2000002214, "trilha": "fiscal", "materia": "aud", "assunto": "Evidência", "tipo": "pergunta", "frente": "Qual evidência é mais confiável: obtida de fonte externa ou interna?", "verso": "Externa e independente da entidade.", "explicacao": "NBC TA 500."}, {"id": 2000002215, "trilha": "fiscal", "materia": "aud", "assunto": "Evidência", "tipo": "pergunta", "frente": "Cite outras regras de confiabilidade da evidência.", "verso": "Obtida diretamente pelo auditor é mais confiável que a indireta; documental é mais confiável que a oral; documento original é mais confiável que fotocópia; gerada com controles efetivos é mais confiável.", "explicacao": "NBC TA 500."}, {"id": 2000002216, "trilha": "fiscal", "materia": "aud", "assunto": "Evidência", "tipo": "pergunta", "frente": "Quais são os procedimentos de auditoria para obter evidência?", "verso": "Inspeção, observação, confirmação externa, recálculo, reexecução, procedimentos analíticos e indagação.", "explicacao": "NBC TA 500."}, {"id": 2000002217, "trilha": "fiscal", "materia": "aud", "assunto": "Evidência", "tipo": "pares", "frente": "Inspeção x observação.", "verso": "Inspeção: exame de registros, documentos ou ativos físicos. Observação: acompanhar um processo executado por outros (ex.: contagem de estoque pelos empregados).", "explicacao": ""}, {"id": 2000002218, "trilha": "fiscal", "materia": "aud", "assunto": "Evidência", "tipo": "pares", "frente": "Recálculo x reexecução.", "verso": "Recálculo: verificar a exatidão matemática de documentos ou registros. Reexecução: o auditor executa de forma independente procedimentos ou controles originalmente feitos pela entidade.", "explicacao": ""}, {"id": 2000002219, "trilha": "fiscal", "materia": "aud", "assunto": "Evidência", "tipo": "pergunta", "frente": "A indagação sozinha é suficiente como evidência?", "verso": "Não. Normalmente não fornece evidência suficiente sobre a eficácia operacional dos controles nem sobre a inexistência de distorção.", "explicacao": "NBC TA 500."}, {"id": 2000002220, "trilha": "fiscal", "materia": "aud", "assunto": "Evidência", "tipo": "pares", "frente": "Confirmação positiva x negativa.", "verso": "Positiva: a parte confirmante responde em qualquer caso, concordando ou não. Negativa: só responde se discordar das informações.", "explicacao": "A negativa oferece evidência menos persuasiva. NBC TA 505."}, {"id": 2000002221, "trilha": "fiscal", "materia": "aud", "assunto": "Evidência", "tipo": "pares", "frente": "Confirmação positiva em branco x preenchida.", "verso": "Em branco: o confirmante informa o saldo sem vê-lo, gera mais evidência. Preenchida: o saldo vai indicado e o confirmante concorda ou não.", "explicacao": ""}, {"id": 2000002222, "trilha": "fiscal", "materia": "aud", "assunto": "Evidência", "tipo": "pergunta", "frente": "Quando o auditor deve acompanhar a contagem física dos estoques?", "verso": "Quando os estoques forem relevantes para as demonstrações, salvo impraticabilidade.", "explicacao": "NBC TA 501."}, {"id": 2000002223, "trilha": "fiscal", "materia": "aud", "assunto": "Procedimentos", "tipo": "pares", "frente": "Testes de controle x procedimentos substantivos.", "verso": "Testes de controle: avaliam a eficácia operacional dos controles. Substantivos: detectam distorções relevantes no nível das afirmações (testes de detalhes e procedimentos analíticos substantivos).", "explicacao": "NBC TA 330."}, {"id": 2000002224, "trilha": "fiscal", "materia": "aud", "assunto": "Procedimentos", "tipo": "pergunta", "frente": "Os procedimentos substantivos podem ser dispensados se os controles forem eficazes?", "verso": "Não. Independentemente do risco avaliado, o auditor deve executar procedimentos substantivos para cada classe relevante de transações, saldo e divulgação.", "explicacao": "NBC TA 330."}, {"id": 2000002225, "trilha": "fiscal", "materia": "aud", "assunto": "Procedimentos", "tipo": "pergunta", "frente": "O que são procedimentos analíticos?", "verso": "Avaliações de informações contábeis por meio da análise de relações plausíveis entre dados contábeis e não contábeis.", "explicacao": "NBC TA 520. Obrigatórios na avaliação de riscos e na conclusão."}, {"id": 2000002226, "trilha": "fiscal", "materia": "aud", "assunto": "Amostragem", "tipo": "pares", "frente": "Amostragem estatística x não estatística.", "verso": "Estatística: seleção aleatória e uso da teoria da probabilidade para avaliar os resultados. Não estatística: baseada no julgamento do auditor.", "explicacao": "NBC TA 530."}, {"id": 2000002227, "trilha": "fiscal", "materia": "aud", "assunto": "Amostragem", "tipo": "pares", "frente": "Risco de amostragem: aceitação incorreta x rejeição incorreta.", "verso": "Aceitação incorreta: concluir que não há distorção relevante quando há; afeta a eficácia. Rejeição incorreta: concluir que há distorção quando não há; afeta a eficiência.", "explicacao": "NBC TA 530."}, {"id": 2000002228, "trilha": "fiscal", "materia": "aud", "assunto": "Amostragem", "tipo": "pares", "frente": "Seleção aleatória x sistemática x ao acaso.", "verso": "Aleatória: por gerador de números aleatórios. Sistemática: intervalo constante a partir de um ponto inicial. Ao acaso: o auditor escolhe sem seguir técnica estruturada, evitando vieses.", "explicacao": "NBC TA 530."}, {"id": 2000002229, "trilha": "fiscal", "materia": "aud", "assunto": "Controle interno", "tipo": "pergunta", "frente": "Quais os componentes do controle interno (COSO)?", "verso": "Ambiente de controle, avaliação de riscos, atividades de controle, informação e comunicação e atividades de monitoramento.", "explicacao": "COSO 2013."}, {"id": 2000002230, "trilha": "fiscal", "materia": "aud", "assunto": "Controle interno", "tipo": "pergunta", "frente": "O que é segregação de funções?", "verso": "Separar funções incompatíveis (autorizar, executar, registrar e custodiar) para que uma pessoa não controle todo o processo.", "explicacao": "Reduz o risco de erro e fraude."}, {"id": 2000002231, "trilha": "fiscal", "materia": "aud", "assunto": "Controle interno", "tipo": "pares", "frente": "Controles preventivos x detectivos.", "verso": "Preventivos: evitam que o erro ocorra (autorização prévia, segregação). Detectivos: identificam o erro depois que ocorreu (conciliação bancária, inventário).", "explicacao": ""}, {"id": 2000002232, "trilha": "fiscal", "materia": "aud", "assunto": "Controle interno", "tipo": "pergunta", "frente": "O que é deficiência significativa de controle interno?", "verso": "Deficiência ou combinação de deficiências que, no julgamento do auditor, é importante o suficiente para merecer a atenção dos responsáveis pela governança.", "explicacao": "NBC TA 265. Deve ser comunicada por escrito."}, {"id": 2000002233, "trilha": "fiscal", "materia": "aud", "assunto": "Controle interno", "tipo": "pergunta", "frente": "Quais as limitações do controle interno?", "verso": "Erro humano, conluio entre pessoas, burla pela administração e custo maior que o benefício.", "explicacao": ""}, {"id": 2000002234, "trilha": "fiscal", "materia": "aud", "assunto": "Controle interno", "tipo": "pergunta", "frente": "O que é o modelo das três linhas (IIA)?", "verso": "1ª linha: gestão operacional que possui e gerencia riscos. 2ª: funções de gerenciamento de riscos e conformidade. 3ª: auditoria interna, com avaliação independente.", "explicacao": "Atualização de 2020 do modelo das três linhas de defesa."}, {"id": 2000002235, "trilha": "fiscal", "materia": "aud", "assunto": "Relatório", "tipo": "pergunta", "frente": "Quais os tipos de opinião do auditor?", "verso": "Não modificada (sem ressalva) e modificadas: com ressalva, adversa e abstenção de opinião.", "explicacao": "NBC TA 700 e 705."}, {"id": 2000002236, "trilha": "fiscal", "materia": "aud", "assunto": "Relatório", "tipo": "pares", "frente": "Opinião com ressalva x adversa.", "verso": "Com ressalva: distorções relevantes, mas não generalizadas (ou limitação não generalizada). Adversa: distorções relevantes e generalizadas.", "explicacao": "NBC TA 705."}, {"id": 2000002237, "trilha": "fiscal", "materia": "aud", "assunto": "Relatório", "tipo": "pergunta", "frente": "Quando o auditor se abstém de opinar?", "verso": "Quando não consegue obter evidência suficiente e apropriada e os possíveis efeitos de distorções não detectadas poderiam ser relevantes e generalizados.", "explicacao": "NBC TA 705."}, {"id": 2000002238, "trilha": "fiscal", "materia": "aud", "assunto": "Relatório", "tipo": "pares", "frente": "Parágrafo de ênfase x parágrafo de outros assuntos.", "verso": "Ênfase: chama atenção para assunto apresentado nas demonstrações, fundamental para o entendimento pelos usuários. Outros assuntos: tema não apresentado nas demonstrações, relevante para entender a auditoria ou o relatório.", "explicacao": "NBC TA 706. Nenhum dos dois modifica a opinião."}, {"id": 2000002239, "trilha": "fiscal", "materia": "aud", "assunto": "Relatório", "tipo": "pergunta", "frente": "O que são os principais assuntos de auditoria (PAA)?", "verso": "Assuntos que, no julgamento do auditor, foram os mais significativos na auditoria do período, comunicados no relatório.", "explicacao": "NBC TA 701. Obrigatório para companhias abertas."}, {"id": 2000002240, "trilha": "fiscal", "materia": "aud", "assunto": "Relatório", "tipo": "pergunta", "frente": "Como o auditor trata a incerteza relevante sobre continuidade operacional adequadamente divulgada?", "verso": "Inclui no relatório uma seção “Incerteza relevante relacionada com a continuidade operacional”, sem modificar a opinião.", "explicacao": "NBC TA 570."}, {"id": 2000002241, "trilha": "fiscal", "materia": "aud", "assunto": "Eventos subsequentes", "tipo": "pares", "frente": "Evento subsequente que gera ajuste x que não gera ajuste.", "verso": "Gera ajuste: evidencia condição que já existia na data do balanço (ex.: falência de cliente com dívida antiga). Não gera ajuste: indica condição surgida após a data do balanço (ex.: incêndio posterior); apenas divulgação.", "explicacao": "NBC TA 560 e CPC 24."}, {"id": 2000002242, "trilha": "fiscal", "materia": "aud", "assunto": "Representações", "tipo": "pergunta", "frente": "O que é a carta de representação?", "verso": "Declaração escrita da administração confirmando certos assuntos ou sustentando outras evidências de auditoria.", "explicacao": "NBC TA 580. Não substitui outras evidências."}, {"id": 2000002243, "trilha": "fiscal", "materia": "aud", "assunto": "Documentação", "tipo": "pergunta", "frente": "O que são os papéis de trabalho?", "verso": "Registro dos procedimentos executados, da evidência obtida e das conclusões alcançadas pelo auditor.", "explicacao": "NBC TA 230. Pertencem ao auditor."}, {"id": 2000002244, "trilha": "fiscal", "materia": "aud", "assunto": "Documentação", "tipo": "pergunta", "frente": "Por quanto tempo devem ser guardados os papéis de trabalho?", "verso": "Pelo prazo mínimo de 5 anos a partir da data do relatório do auditor.", "explicacao": "NBC TA 230 e NBC PA 01."}, {"id": 2000002245, "trilha": "fiscal", "materia": "aud", "assunto": "Ética", "tipo": "pergunta", "frente": "Quais as ameaças à independência do auditor?", "verso": "Interesse próprio, autorrevisão, defesa de interesse do cliente, familiaridade e intimidação.", "explicacao": "Código de Ética (NBC PG 100)."}, {"id": 2000002246, "trilha": "fiscal", "materia": "aud", "assunto": "Ética", "tipo": "pergunta", "frente": "Qual o rodízio exigido de auditores independentes de companhias abertas pela CVM?", "verso": "O auditor não pode prestar serviços ao mesmo cliente por mais de 5 anos consecutivos, com intervalo mínimo de 3 anos; o prazo vai a 10 anos se houver comitê de auditoria estatutário.", "explicacao": "Resolução CVM 23/2021."}, {"id": 2000002247, "trilha": "fiscal", "materia": "aud", "assunto": "Auditoria governamental", "tipo": "pergunta", "frente": "Quais as normas que orientam a auditoria do setor público no Brasil?", "verso": "As NBASP (Normas Brasileiras de Auditoria do Setor Público), baseadas nas ISSAI da Intosai.", "explicacao": ""}, {"id": 2000002248, "trilha": "fiscal", "materia": "aud", "assunto": "Auditoria governamental", "tipo": "pares", "frente": "Auditoria financeira x de conformidade x operacional.", "verso": "Financeira: opinião sobre as demonstrações. Conformidade: verifica se as atividades obedecem a leis e normas. Operacional (de desempenho): avalia economicidade, eficiência, eficácia e efetividade.", "explicacao": "Classificação das ISSAI."}, {"id": 2000002249, "trilha": "fiscal", "materia": "aud", "assunto": "Auditoria governamental", "tipo": "pergunta", "frente": "Quem compõe o sistema de controle interno do Poder Executivo Federal?", "verso": "A Controladoria-Geral da União (CGU) é o órgão central.", "explicacao": "CF, art. 74."}, {"id": 2000002250, "trilha": "fiscal", "materia": "aud", "assunto": "Auditoria governamental", "tipo": "pergunta", "frente": "O que acontece se o responsável pelo controle interno souber de irregularidade e não comunicar ao TCU?", "verso": "Responde solidariamente.", "explicacao": "CF, art. 74, § 1º."}, {"id": 2000002251, "trilha": "fiscal", "materia": "aud", "assunto": "Auditoria governamental", "tipo": "pergunta", "frente": "Quem pode denunciar irregularidades ao Tribunal de Contas da União?", "verso": "Qualquer cidadão, partido político, associação ou sindicato.", "explicacao": "CF, art. 74, § 2º."}, {"id": 2000002252, "trilha": "fiscal", "materia": "aud", "assunto": "Auditoria governamental", "tipo": "pares", "frente": "Economicidade x eficiência x eficácia x efetividade.", "verso": "Economicidade: menor custo dos insumos sem perder qualidade. Eficiência: relação entre produtos e insumos. Eficácia: alcance das metas. Efetividade: impacto real na sociedade.", "explicacao": "Dimensões da auditoria operacional."}, {"id": 2000002253, "trilha": "fiscal", "materia": "aud", "assunto": "Auditoria interna", "tipo": "pergunta", "frente": "O que define a auditoria interna segundo o IIA?", "verso": "Atividade independente e objetiva de avaliação e consultoria, para agregar valor e melhorar as operações da organização.", "explicacao": ""}, {"id": 2000002254, "trilha": "fiscal", "materia": "aud", "assunto": "Auditoria interna", "tipo": "pergunta", "frente": "A quem a auditoria interna deve se reportar para preservar sua independência?", "verso": "Funcionalmente ao conselho ou órgão de governança (como o comitê de auditoria).", "explicacao": ""}, {"id": 2000002255, "trilha": "fiscal", "materia": "aud", "assunto": "Trabalho de outros", "tipo": "pergunta", "frente": "O auditor externo pode usar o trabalho da auditoria interna?", "verso": "Sim, após avaliar a objetividade, competência e abordagem sistemática da função, mas a responsabilidade pela opinião é exclusivamente dele.", "explicacao": "NBC TA 610."}, {"id": 2000002256, "trilha": "fiscal", "materia": "aud", "assunto": "Trabalho de outros", "tipo": "pergunta", "frente": "O auditor pode dividir a responsabilidade da opinião com especialista que contratou?", "verso": "Não. A responsabilidade é exclusiva do auditor, e ele não faz referência ao especialista no relatório com opinião não modificada.", "explicacao": "NBC TA 620."}, {"id": 2000002257, "trilha": "fiscal", "materia": "aud", "assunto": "Comunicação", "tipo": "pergunta", "frente": "O que o auditor deve comunicar aos responsáveis pela governança?", "verso": "Responsabilidades do auditor, alcance e época da auditoria, constatações significativas e independência (em entidades listadas).", "explicacao": "NBC TA 260."}, {"id": 2000002258, "trilha": "fiscal", "materia": "aud", "assunto": "Fraude", "tipo": "pergunta", "frente": "Que procedimento é obrigatório para responder ao risco de burla de controles pela administração?", "verso": "Testar lançamentos contábeis manuais e ajustes, revisar estimativas contábeis em busca de vieses e avaliar transações significativas fora do curso normal.", "explicacao": "NBC TA 240."}, {"id": 2000002259, "trilha": "fiscal", "materia": "aud", "assunto": "Fraude", "tipo": "pergunta", "frente": "O reconhecimento de receita é presumido como risco de fraude?", "verso": "Sim, o auditor deve presumir que há riscos de fraude no reconhecimento de receita, salvo se concluir o contrário e documentar.", "explicacao": "NBC TA 240."}, {"id": 2000002260, "trilha": "fiscal", "materia": "eco", "assunto": "Conceitos", "tipo": "pergunta", "frente": "Qual o problema econômico fundamental?", "verso": "A escassez: recursos limitados diante de necessidades ilimitadas, que obriga a fazer escolhas.", "explicacao": "Toda escolha tem custo de oportunidade."}, {"id": 2000002261, "trilha": "fiscal", "materia": "eco", "assunto": "Conceitos", "tipo": "pergunta", "frente": "O que é custo de oportunidade?", "verso": "O valor da melhor alternativa de que se abre mão ao fazer uma escolha.", "explicacao": ""}, {"id": 2000002262, "trilha": "fiscal", "materia": "eco", "assunto": "Conceitos", "tipo": "pergunta", "frente": "O que mostra a curva de possibilidades de produção?", "verso": "As combinações máximas de dois bens que uma economia pode produzir com os recursos e a tecnologia disponíveis.", "explicacao": "Pontos internos: ineficiência; pontos externos: inatingíveis."}, {"id": 2000002263, "trilha": "fiscal", "materia": "eco", "assunto": "Conceitos", "tipo": "pares", "frente": "Microeconomia x macroeconomia.", "verso": "Micro: estuda o comportamento de consumidores, empresas e mercados específicos. Macro: estuda agregados da economia (PIB, inflação, desemprego, câmbio).", "explicacao": ""}, {"id": 2000002264, "trilha": "fiscal", "materia": "eco", "assunto": "Conceitos", "tipo": "pares", "frente": "Economia positiva x normativa.", "verso": "Positiva: descreve o que é (fatos verificáveis). Normativa: diz o que deveria ser (juízos de valor).", "explicacao": ""}, {"id": 2000002265, "trilha": "fiscal", "materia": "eco", "assunto": "Demanda e oferta", "tipo": "pergunta", "frente": "O que diz a lei da demanda?", "verso": "Coeteris paribus, quando o preço de um bem sobe, a quantidade demandada cai.", "explicacao": "Curva de demanda negativamente inclinada."}, {"id": 2000002266, "trilha": "fiscal", "materia": "eco", "assunto": "Demanda e oferta", "tipo": "pares", "frente": "Variação da quantidade demandada x deslocamento da curva de demanda.", "verso": "Variação da quantidade: movimento ao longo da curva, causado pelo próprio preço do bem. Deslocamento: causado por outros fatores (renda, preços de outros bens, gostos, expectativas).", "explicacao": ""}, {"id": 2000002267, "trilha": "fiscal", "materia": "eco", "assunto": "Demanda e oferta", "tipo": "pares", "frente": "Bem normal x inferior.", "verso": "Normal: a demanda aumenta quando a renda aumenta. Inferior: a demanda cai quando a renda aumenta (ex.: produtos de segunda linha).", "explicacao": "Bem de Giffen: inferior em que a demanda sobe com o preço."}, {"id": 2000002268, "trilha": "fiscal", "materia": "eco", "assunto": "Demanda e oferta", "tipo": "pares", "frente": "Bens substitutos x complementares.", "verso": "Substitutos: o aumento do preço de um aumenta a demanda do outro (manteiga e margarina). Complementares: o aumento do preço de um reduz a demanda do outro (carro e gasolina).", "explicacao": "Elasticidade-preço cruzada positiva (substitutos) ou negativa (complementares)."}, {"id": 2000002269, "trilha": "fiscal", "materia": "eco", "assunto": "Demanda e oferta", "tipo": "pergunta", "frente": "O que acontece com o preço e a quantidade de equilíbrio quando a demanda aumenta?", "verso": "Ambos aumentam (com oferta inalterada).", "explicacao": ""}, {"id": 2000002270, "trilha": "fiscal", "materia": "eco", "assunto": "Demanda e oferta", "tipo": "pergunta", "frente": "O que causa um preço máximo (tabelamento) abaixo do equilíbrio?", "verso": "Excesso de demanda (escassez), filas e mercado paralelo.", "explicacao": "Preço mínimo acima do equilíbrio gera excesso de oferta."}, {"id": 2000002271, "trilha": "fiscal", "materia": "eco", "assunto": "Elasticidade", "tipo": "pergunta", "frente": "Quando a demanda é elástica?", "verso": "Quando a elasticidade-preço, em módulo, é maior que 1: a quantidade varia proporcionalmente mais que o preço.", "explicacao": "Inelástica: menor que 1."}, {"id": 2000002272, "trilha": "fiscal", "materia": "eco", "assunto": "Elasticidade", "tipo": "pergunta", "frente": "Se a demanda é inelástica e o preço sobe, o que acontece com a receita total?", "verso": "Aumenta.", "explicacao": "Se elástica, a receita cai quando o preço sobe."}, {"id": 2000002273, "trilha": "fiscal", "materia": "eco", "assunto": "Elasticidade", "tipo": "pergunta", "frente": "Quais fatores tornam a demanda mais elástica?", "verso": "Muitos substitutos, bem supérfluo, grande peso no orçamento e maior prazo de ajuste.", "explicacao": ""}, {"id": 2000002274, "trilha": "fiscal", "materia": "eco", "assunto": "Elasticidade", "tipo": "pergunta", "frente": "Quem arca com a maior parte de um imposto sobre um bem?", "verso": "O lado mais inelástico do mercado (consumidores ou produtores).", "explicacao": "Incidência tributária."}, {"id": 2000002275, "trilha": "fiscal", "materia": "eco", "assunto": "Consumidor", "tipo": "pergunta", "frente": "O que diz a utilidade marginal decrescente?", "verso": "Cada unidade adicional consumida de um bem gera menos satisfação que a anterior.", "explicacao": ""}, {"id": 2000002276, "trilha": "fiscal", "materia": "eco", "assunto": "Produção e custos", "tipo": "pergunta", "frente": "O que diz a lei dos rendimentos decrescentes?", "verso": "Ao aumentar um fator variável mantendo outro fixo, a partir de certo ponto o produto marginal começa a cair.", "explicacao": "Curto prazo."}, {"id": 2000002277, "trilha": "fiscal", "materia": "eco", "assunto": "Produção e custos", "tipo": "pares", "frente": "Curto prazo x longo prazo na produção.", "verso": "Curto prazo: pelo menos um fator é fixo. Longo prazo: todos os fatores são variáveis.", "explicacao": ""}, {"id": 2000002278, "trilha": "fiscal", "materia": "eco", "assunto": "Produção e custos", "tipo": "pares", "frente": "Economias de escala x deseconomias de escala.", "verso": "Economias: o custo médio de longo prazo cai quando a produção aumenta. Deseconomias: o custo médio sobe com a produção.", "explicacao": ""}, {"id": 2000002279, "trilha": "fiscal", "materia": "eco", "assunto": "Produção e custos", "tipo": "pergunta", "frente": "Qual a condição de maximização de lucro de uma empresa?", "verso": "Produzir até o ponto em que a receita marginal é igual ao custo marginal.", "explicacao": "RMg = CMg."}, {"id": 2000002280, "trilha": "fiscal", "materia": "eco", "assunto": "Estruturas de mercado", "tipo": "pergunta", "frente": "Quais as características da concorrência perfeita?", "verso": "Muitos compradores e vendedores, produto homogêneo, livre entrada e saída, informação perfeita; empresas são tomadoras de preço.", "explicacao": "No longo prazo, lucro econômico zero."}, {"id": 2000002281, "trilha": "fiscal", "materia": "eco", "assunto": "Estruturas de mercado", "tipo": "pergunta", "frente": "Como o monopolista define preço e quantidade em relação à concorrência perfeita?", "verso": "Produz menos e cobra mais, gerando peso morto (perda de eficiência).", "explicacao": "Monopólio natural: um único produtor tem custo menor (ex.: saneamento)."}, {"id": 2000002282, "trilha": "fiscal", "materia": "eco", "assunto": "Estruturas de mercado", "tipo": "pares", "frente": "Oligopólio x concorrência monopolística.", "verso": "Oligopólio: poucas empresas interdependentes, com barreiras à entrada (ex.: telefonia). Concorrência monopolística: muitas empresas com produtos diferenciados e livre entrada (ex.: restaurantes).", "explicacao": ""}, {"id": 2000002283, "trilha": "fiscal", "materia": "eco", "assunto": "Estruturas de mercado", "tipo": "pares", "frente": "Monopsônio x oligopsônio.", "verso": "Monopsônio: um único comprador. Oligopsônio: poucos compradores.", "explicacao": ""}, {"id": 2000002284, "trilha": "fiscal", "materia": "eco", "assunto": "Estruturas de mercado", "tipo": "pergunta", "frente": "O que é cartel?", "verso": "Acordo entre concorrentes para fixar preços ou dividir mercados, agindo como monopólio.", "explicacao": "Crime e infração à ordem econômica; o CADE combate."}, {"id": 2000002285, "trilha": "fiscal", "materia": "eco", "assunto": "Falhas de mercado", "tipo": "pergunta", "frente": "Quais são as falhas de mercado?", "verso": "Bens públicos, externalidades, assimetria de informação, poder de mercado (monopólios) e mercados incompletos.", "explicacao": "Justificam a intervenção do Estado."}, {"id": 2000002286, "trilha": "fiscal", "materia": "eco", "assunto": "Falhas de mercado", "tipo": "pergunta", "frente": "Quais as características de um bem público puro?", "verso": "Não rival (o consumo de um não reduz o de outro) e não excludente (não se pode impedir o uso).", "explicacao": "Ex.: defesa nacional, iluminação pública. Gera o problema do carona (free rider)."}, {"id": 2000002287, "trilha": "fiscal", "materia": "eco", "assunto": "Falhas de mercado", "tipo": "pares", "frente": "Externalidade positiva x negativa.", "verso": "Positiva: benefício a terceiros sem compensação (vacinação, educação). Negativa: custo a terceiros sem compensação (poluição).", "explicacao": "Imposto de Pigou corrige externalidades negativas."}, {"id": 2000002288, "trilha": "fiscal", "materia": "eco", "assunto": "Falhas de mercado", "tipo": "pares", "frente": "Seleção adversa x risco moral.", "verso": "Seleção adversa: assimetria de informação antes do contrato (só os de alto risco compram seguro). Risco moral: mudança de comportamento após o contrato (segurado fica menos cuidadoso).", "explicacao": ""}, {"id": 2000002289, "trilha": "fiscal", "materia": "eco", "assunto": "Falhas de mercado", "tipo": "pergunta", "frente": "O que diz o teorema de Coase?", "verso": "Se os direitos de propriedade forem bem definidos e os custos de transação forem baixos, as partes negociam e resolvem a externalidade de forma eficiente.", "explicacao": ""}, {"id": 2000002290, "trilha": "fiscal", "materia": "eco", "assunto": "Contas nacionais", "tipo": "pergunta", "frente": "O que é o PIB?", "verso": "Valor de todos os bens e serviços finais produzidos dentro do território do país em determinado período.", "explicacao": "Não inclui bens intermediários, para evitar dupla contagem."}, {"id": 2000002291, "trilha": "fiscal", "materia": "eco", "assunto": "Contas nacionais", "tipo": "lacuna", "frente": "Pela ótica da despesa, PIB = C + I + G + (___ − ___).", "verso": "Exportações − importações (X − M).", "explicacao": "C: consumo; I: investimento; G: gastos do governo."}, {"id": 2000002292, "trilha": "fiscal", "materia": "eco", "assunto": "Contas nacionais", "tipo": "pares", "frente": "PIB x PNB.", "verso": "PIB: produção dentro do território, por residentes ou não. PNB: produção dos residentes, dentro ou fora do país. PNB = PIB − renda líquida enviada ao exterior.", "explicacao": "No Brasil, em regra, PNB < PIB."}, {"id": 2000002293, "trilha": "fiscal", "materia": "eco", "assunto": "Contas nacionais", "tipo": "pares", "frente": "PIB nominal x real.", "verso": "Nominal: a preços correntes. Real: a preços constantes de um ano-base, descontando a inflação.", "explicacao": "Deflator do PIB = nominal ÷ real × 100."}, {"id": 2000002294, "trilha": "fiscal", "materia": "eco", "assunto": "Contas nacionais", "tipo": "pares", "frente": "Valores a preços de mercado x a custo de fatores.", "verso": "Preço de mercado inclui impostos indiretos e exclui subsídios. Custo de fatores = preço de mercado − impostos indiretos + subsídios.", "explicacao": ""}, {"id": 2000002295, "trilha": "fiscal", "materia": "eco", "assunto": "Contas nacionais", "tipo": "pergunta", "frente": "Quais as três óticas de cálculo do PIB?", "verso": "Produto (valor adicionado), despesa (demanda) e renda.", "explicacao": "As três chegam ao mesmo valor."}, {"id": 2000002296, "trilha": "fiscal", "materia": "eco", "assunto": "Contas nacionais", "tipo": "pergunta", "frente": "Qual a identidade macroeconômica entre poupança e investimento?", "verso": "Investimento = poupança privada + poupança do governo + poupança externa.", "explicacao": ""}, {"id": 2000002297, "trilha": "fiscal", "materia": "eco", "assunto": "Contas nacionais", "tipo": "pergunta", "frente": "O que mede o índice de Gini?", "verso": "A concentração de renda, de 0 (igualdade perfeita) a 1 (desigualdade máxima).", "explicacao": "Ligado à curva de Lorenz."}, {"id": 2000002298, "trilha": "fiscal", "materia": "eco", "assunto": "Inflação", "tipo": "pares", "frente": "Inflação de demanda x de custos.", "verso": "Demanda: excesso de demanda agregada em relação à oferta. Custos: aumento dos custos de produção (salários, matérias-primas, câmbio).", "explicacao": "Há também a inflação inercial, pela indexação."}, {"id": 2000002299, "trilha": "fiscal", "materia": "eco", "assunto": "Inflação", "tipo": "pergunta", "frente": "Qual o índice usado no regime de metas de inflação do Brasil?", "verso": "O IPCA, calculado pelo IBGE.", "explicacao": "A meta é definida pelo Conselho Monetário Nacional."}, {"id": 2000002300, "trilha": "fiscal", "materia": "eco", "assunto": "Inflação", "tipo": "pergunta", "frente": "Como funciona a meta de inflação contínua adotada a partir de 2025?", "verso": "A meta é considerada descumprida se a inflação acumulada em 12 meses ficar fora do intervalo de tolerância por 6 meses consecutivos.", "explicacao": "Meta de 3%, com tolerância de 1,5 ponto percentual."}, {"id": 2000002301, "trilha": "fiscal", "materia": "eco", "assunto": "Inflação", "tipo": "pergunta", "frente": "O que é estagflação?", "verso": "Estagnação econômica (ou recessão) combinada com inflação alta.", "explicacao": "Típica de choques de oferta, como os do petróleo nos anos 1970."}, {"id": 2000002302, "trilha": "fiscal", "materia": "eco", "assunto": "Inflação", "tipo": "pergunta", "frente": "O que diz a curva de Phillips?", "verso": "No curto prazo, há relação inversa entre inflação e desemprego.", "explicacao": "No longo prazo, a curva tende a ser vertical (taxa natural de desemprego)."}, {"id": 2000002303, "trilha": "fiscal", "materia": "eco", "assunto": "Política monetária", "tipo": "pergunta", "frente": "Quais os instrumentos de política monetária?", "verso": "Operações de mercado aberto, depósito compulsório, redesconto e controle direto do crédito.", "explicacao": "O principal hoje é a taxa Selic, via operações de mercado aberto."}, {"id": 2000002304, "trilha": "fiscal", "materia": "eco", "assunto": "Política monetária", "tipo": "pergunta", "frente": "Que efeito tem a alta da taxa Selic?", "verso": "Encarece o crédito, reduz consumo e investimento, contém a inflação e tende a valorizar o real.", "explicacao": "Política monetária contracionista."}, {"id": 2000002305, "trilha": "fiscal", "materia": "eco", "assunto": "Política monetária", "tipo": "pergunta", "frente": "O que acontece com a oferta de moeda quando o Banco Central vende títulos públicos?", "verso": "Diminui, porque o BC recolhe moeda da economia.", "explicacao": "Comprar títulos aumenta a oferta de moeda."}, {"id": 2000002306, "trilha": "fiscal", "materia": "eco", "assunto": "Política monetária", "tipo": "pergunta", "frente": "Quem define a meta da taxa Selic?", "verso": "O Copom (Comitê de Política Monetária) do Banco Central.", "explicacao": "Reúne-se 8 vezes por ano."}, {"id": 2000002307, "trilha": "fiscal", "materia": "eco", "assunto": "Política monetária", "tipo": "pergunta", "frente": "O que é o multiplicador monetário?", "verso": "Quanto a base monetária se multiplica em meios de pagamento, por causa da criação de moeda pelos bancos via empréstimos.", "explicacao": "Quanto maior o compulsório, menor o multiplicador."}, {"id": 2000002308, "trilha": "fiscal", "materia": "eco", "assunto": "Política monetária", "tipo": "pares", "frente": "Base monetária x meios de pagamento (M1).", "verso": "Base monetária: papel-moeda emitido mais reservas bancárias. M1: papel-moeda em poder do público mais depósitos à vista.", "explicacao": ""}, {"id": 2000002309, "trilha": "fiscal", "materia": "eco", "assunto": "Política fiscal", "tipo": "pergunta", "frente": "O que é política fiscal expansionista?", "verso": "Aumento dos gastos públicos ou redução de impostos para estimular a demanda agregada.", "explicacao": ""}, {"id": 2000002310, "trilha": "fiscal", "materia": "eco", "assunto": "Política fiscal", "tipo": "pergunta", "frente": "O que é o multiplicador keynesiano dos gastos?", "verso": "Um aumento do gasto autônomo eleva a renda em um valor maior: multiplicador = 1 ÷ (1 − propensão marginal a consumir).", "explicacao": "Ex.: PMgC = 0,8 → multiplicador = 5."}, {"id": 2000002311, "trilha": "fiscal", "materia": "eco", "assunto": "Política fiscal", "tipo": "pergunta", "frente": "O que é efeito deslocamento (crowding out)?", "verso": "O aumento dos gastos do governo eleva os juros e reduz o investimento privado.", "explicacao": ""}, {"id": 2000002312, "trilha": "fiscal", "materia": "eco", "assunto": "Política fiscal", "tipo": "pares", "frente": "Tributo progressivo x regressivo.", "verso": "Progressivo: a alíquota efetiva aumenta com a renda (IR). Regressivo: pesa proporcionalmente mais sobre os mais pobres (impostos sobre consumo).", "explicacao": ""}, {"id": 2000002313, "trilha": "fiscal", "materia": "eco", "assunto": "Política fiscal", "tipo": "pergunta", "frente": "O que mostra a curva de Laffer?", "verso": "A partir de certa alíquota, aumentos de impostos reduzem a arrecadação.", "explicacao": ""}, {"id": 2000002314, "trilha": "fiscal", "materia": "eco", "assunto": "Funções do governo", "tipo": "pergunta", "frente": "Quais as funções do governo segundo Musgrave?", "verso": "Alocativa (oferta de bens públicos), distributiva (redistribuição de renda) e estabilizadora (emprego, preços e crescimento).", "explicacao": ""}, {"id": 2000002315, "trilha": "fiscal", "materia": "eco", "assunto": "Setor externo", "tipo": "pergunta", "frente": "Quais as contas do balanço de pagamentos?", "verso": "Transações correntes (balança comercial, serviços, rendas e transferências), conta capital e conta financeira.", "explicacao": "Metodologia BPM6."}, {"id": 2000002316, "trilha": "fiscal", "materia": "eco", "assunto": "Setor externo", "tipo": "pergunta", "frente": "O que acontece com exportações e importações quando o real se desvaloriza?", "verso": "Exportações ficam mais competitivas (tendem a subir) e importações ficam mais caras (tendem a cair).", "explicacao": ""}, {"id": 2000002317, "trilha": "fiscal", "materia": "eco", "assunto": "Setor externo", "tipo": "pares", "frente": "Câmbio fixo x flutuante.", "verso": "Fixo: o Banco Central mantém a taxa num valor determinado. Flutuante: a taxa é definida pelo mercado. O Brasil adota flutuação suja, com intervenções eventuais.", "explicacao": "Câmbio flutuante desde 1999."}, {"id": 2000002318, "trilha": "fiscal", "materia": "eco", "assunto": "Setor externo", "tipo": "pergunta", "frente": "O que é a teoria das vantagens comparativas (Ricardo)?", "verso": "Cada país deve se especializar no que produz com menor custo de oportunidade relativo, e o comércio beneficia todos.", "explicacao": ""}, {"id": 2000002319, "trilha": "fiscal", "materia": "eco", "assunto": "Setor externo", "tipo": "pergunta", "frente": "O que é o tripé macroeconômico brasileiro?", "verso": "Metas de inflação, câmbio flutuante e metas de superávit primário (responsabilidade fiscal).", "explicacao": "Adotado em 1999."}, {"id": 2000002320, "trilha": "fiscal", "materia": "eco", "assunto": "Mercado financeiro", "tipo": "pergunta", "frente": "Quem regula e fiscaliza o mercado de capitais no Brasil?", "verso": "A Comissão de Valores Mobiliários (CVM).", "explicacao": "Instituições financeiras: Banco Central. Seguros: Susep."}, {"id": 2000002321, "trilha": "fiscal", "materia": "eco", "assunto": "Mercado financeiro", "tipo": "pergunta", "frente": "Qual é o órgão máximo do Sistema Financeiro Nacional?", "verso": "O Conselho Monetário Nacional (CMN).", "explicacao": "Composto pelo Ministro da Fazenda, Ministro do Planejamento e Presidente do Banco Central."}, {"id": 2000002322, "trilha": "fiscal", "materia": "eco", "assunto": "Matemática financeira", "tipo": "pergunta", "frente": "O que é taxa de juros real?", "verso": "Taxa nominal descontada a inflação: (1 + nominal) ÷ (1 + inflação) − 1.", "explicacao": "Equação de Fisher."}, {"id": 2000002323, "trilha": "fiscal", "materia": "eco", "assunto": "Matemática financeira", "tipo": "pergunta", "frente": "O que é valor presente líquido (VPL)?", "verso": "Soma dos fluxos de caixa futuros descontados a uma taxa, menos o investimento inicial. VPL > 0 indica projeto viável.", "explicacao": ""}, {"id": 2000002324, "trilha": "fiscal", "materia": "eco", "assunto": "Matemática financeira", "tipo": "pergunta", "frente": "O que é taxa interna de retorno (TIR)?", "verso": "Taxa de desconto que torna o VPL igual a zero.", "explicacao": "Projeto viável se a TIR for maior que a taxa mínima de atratividade."}, {"id": 2000002325, "trilha": "fiscal", "materia": "eco", "assunto": "Matemática financeira", "tipo": "pares", "frente": "Sistema Price x SAC.", "verso": "Price: prestações constantes; amortização crescente e juros decrescentes. SAC: amortização constante; prestações e juros decrescentes.", "explicacao": "No SAC, a primeira prestação é maior."}, {"id": 2000002326, "trilha": "fiscal", "materia": "eco", "assunto": "Matemática financeira", "tipo": "pergunta", "frente": "Como converter taxa de 1% ao mês em taxa anual composta?", "verso": "(1,01)¹² − 1 ≈ 12,68% ao ano.", "explicacao": "Taxas equivalentes, não proporcionais."}, {"id": 2000002327, "trilha": "fiscal", "materia": "eco", "assunto": "Crescimento", "tipo": "pares", "frente": "Crescimento x desenvolvimento econômico.", "verso": "Crescimento: aumento da produção (PIB). Desenvolvimento: crescimento acompanhado de melhora nas condições de vida (saúde, educação, distribuição de renda).", "explicacao": ""}, {"id": 2000002328, "trilha": "fiscal", "materia": "eco", "assunto": "Crescimento", "tipo": "pergunta", "frente": "Do que depende o crescimento de longo prazo no modelo de Solow?", "verso": "Do progresso tecnológico; acumular capital sozinho tem retornos decrescentes.", "explicacao": ""}, {"id": 2000002329, "trilha": "fiscal", "materia": "eco", "assunto": "Teoria dos jogos", "tipo": "pergunta", "frente": "O que é o equilíbrio de Nash?", "verso": "Situação em que nenhum jogador pode melhorar seu resultado mudando sozinho de estratégia.", "explicacao": "Dilema dos prisioneiros: o equilíbrio não é o melhor resultado conjunto."}, {"id": 2000002330, "trilha": "fiscal", "materia": "adua", "assunto": "Território aduaneiro", "tipo": "pergunta", "frente": "O que compreende o território aduaneiro?", "verso": "Todo o território nacional.", "explicacao": "Regulamento Aduaneiro (Decreto 6.759/2009), art. 2º."}, {"id": 2000002331, "trilha": "fiscal", "materia": "adua", "assunto": "Território aduaneiro", "tipo": "pares", "frente": "Zona primária x zona secundária.", "verso": "Primária: portos, aeroportos e pontos de fronteira alfandegados (áreas terrestres e aquáticas). Secundária: o restante do território aduaneiro, incluídas águas territoriais e espaço aéreo.", "explicacao": "Regulamento Aduaneiro, art. 3º."}, {"id": 2000002332, "trilha": "fiscal", "materia": "adua", "assunto": "Território aduaneiro", "tipo": "pergunta", "frente": "O que é recinto alfandegado?", "verso": "Local declarado pela Receita Federal em que podem ocorrer movimentação, armazenagem e despacho aduaneiro de mercadorias sob controle aduaneiro.", "explicacao": "Pode ficar na zona primária ou secundária."}, {"id": 2000002333, "trilha": "fiscal", "materia": "adua", "assunto": "Território aduaneiro", "tipo": "pergunta", "frente": "Qual a precedência da autoridade aduaneira na zona primária e nos pontos de fronteira?", "verso": "A autoridade aduaneira tem precedência sobre os demais setores administrativos, nos termos da lei.", "explicacao": "CF, art. 37, XVIII; Regulamento Aduaneiro, art. 17."}, {"id": 2000002334, "trilha": "fiscal", "materia": "adua", "assunto": "Controle aduaneiro", "tipo": "pergunta", "frente": "Quem administra e fiscaliza o comércio exterior?", "verso": "O Ministério da Fazenda, por meio da Receita Federal, quanto à fiscalização aduaneira.", "explicacao": "CF, art. 237."}, {"id": 2000002335, "trilha": "fiscal", "materia": "adua", "assunto": "Controle aduaneiro", "tipo": "pergunta", "frente": "Qual sistema informatiza os registros de comércio exterior?", "verso": "O Siscomex (Sistema Integrado de Comércio Exterior), hoje com o Portal Único.", "explicacao": "Declaração Única de Importação (Duimp) e de Exportação (DU-E)."}, {"id": 2000002336, "trilha": "fiscal", "materia": "adua", "assunto": "Imposto de importação", "tipo": "pergunta", "frente": "Qual o fato gerador do imposto de importação?", "verso": "A entrada de produto estrangeiro no território nacional.", "explicacao": "CTN, art. 19."}, {"id": 2000002337, "trilha": "fiscal", "materia": "adua", "assunto": "Imposto de importação", "tipo": "pergunta", "frente": "Para fins de cálculo, quando se considera ocorrido o fato gerador do II, em regra?", "verso": "Na data do registro da declaração de importação de mercadoria submetida a despacho para consumo.", "explicacao": "Decreto-Lei 37/1966, art. 23."}, {"id": 2000002338, "trilha": "fiscal", "materia": "adua", "assunto": "Imposto de importação", "tipo": "pergunta", "frente": "Quem é contribuinte do imposto de importação?", "verso": "O importador, o destinatário de remessa postal internacional e o adquirente de mercadoria entrepostada.", "explicacao": "Decreto-Lei 37/1966, art. 31."}, {"id": 2000002339, "trilha": "fiscal", "materia": "adua", "assunto": "Imposto de importação", "tipo": "pergunta", "frente": "Qual a base de cálculo do II com alíquota ad valorem?", "verso": "O valor aduaneiro, apurado segundo o Acordo de Valoração Aduaneira (GATT).", "explicacao": "Regulamento Aduaneiro, art. 75."}, {"id": 2000002340, "trilha": "fiscal", "materia": "adua", "assunto": "Imposto de importação", "tipo": "pares", "frente": "Alíquota ad valorem x específica.", "verso": "Ad valorem: percentual sobre o valor aduaneiro. Específica: valor fixo por unidade de medida (por quilo, por litro).", "explicacao": ""}, {"id": 2000002341, "trilha": "fiscal", "materia": "adua", "assunto": "Imposto de importação", "tipo": "pergunta", "frente": "O II precisa respeitar a anterioridade?", "verso": "Não. Está fora da anterioridade de exercício e da noventena, e suas alíquotas podem ser alteradas pelo Executivo nos limites da lei.", "explicacao": "CF, arts. 150, § 1º, e 153, § 1º."}, {"id": 2000002342, "trilha": "fiscal", "materia": "adua", "assunto": "Imposto de importação", "tipo": "pergunta", "frente": "Quem altera as alíquotas do II na prática?", "verso": "O Comitê-Executivo de Gestão da Câmara de Comércio Exterior (Gecex/Camex).", "explicacao": ""}, {"id": 2000002343, "trilha": "fiscal", "materia": "adua", "assunto": "Imposto de importação", "tipo": "pergunta", "frente": "Qual nomenclatura classifica as mercadorias no Mercosul?", "verso": "A Nomenclatura Comum do Mercosul (NCM), baseada no Sistema Harmonizado (SH).", "explicacao": "A TEC (Tarifa Externa Comum) define as alíquotas do II."}, {"id": 2000002344, "trilha": "fiscal", "materia": "adua", "assunto": "Imposto de importação", "tipo": "pergunta", "frente": "O que diz o regime de tributação simplificada (RTS)?", "verso": "Permite a cobrança do II com alíquota única sobre remessas postais e encomendas internacionais.", "explicacao": "Hoje há regra específica para compras de até US$ 50 (Remessa Conforme)."}, {"id": 2000002345, "trilha": "fiscal", "materia": "adua", "assunto": "Imposto de importação", "tipo": "pergunta", "frente": "Bagagem acompanhada tem isenção até que valor por via aérea ou marítima?", "verso": "Até US$ 1.000 por viajante, para bens novos, respeitados os limites de quantidade.", "explicacao": "Por via terrestre, fluvial ou lacustre: US$ 500."}, {"id": 2000002346, "trilha": "fiscal", "materia": "adua", "assunto": "Valoração", "tipo": "pergunta", "frente": "Qual o primeiro método de valoração aduaneira?", "verso": "O valor de transação: o preço efetivamente pago ou a pagar pelas mercadorias, com ajustes.", "explicacao": "Acordo de Valoração Aduaneira, art. 1º."}, {"id": 2000002347, "trilha": "fiscal", "materia": "adua", "assunto": "Valoração", "tipo": "pergunta", "frente": "Qual a ordem dos métodos de valoração aduaneira?", "verso": "1º valor de transação; 2º de mercadorias idênticas; 3º de mercadorias similares; 4º dedutivo; 5º computado; 6º último recurso (critério razoável).", "explicacao": "O 4º e o 5º podem ter a ordem invertida a pedido do importador."}, {"id": 2000002348, "trilha": "fiscal", "materia": "adua", "assunto": "Valoração", "tipo": "pergunta", "frente": "Frete e seguro internacionais integram o valor aduaneiro no Brasil?", "verso": "Sim, os custos de transporte e seguro até o porto ou aeroporto de descarga ou ponto de fronteira.", "explicacao": "Base CIF."}, {"id": 2000002349, "trilha": "fiscal", "materia": "adua", "assunto": "Imposto de exportação", "tipo": "pergunta", "frente": "Qual o fato gerador do imposto de exportação?", "verso": "A saída de produto nacional ou nacionalizado do território nacional.", "explicacao": "CTN, art. 23."}, {"id": 2000002350, "trilha": "fiscal", "materia": "adua", "assunto": "Imposto de exportação", "tipo": "pergunta", "frente": "Quando ocorre o fato gerador do imposto de exportação?", "verso": "Na data do registro da declaração de exportação (registro de exportação no Siscomex).", "explicacao": "Regulamento Aduaneiro, art. 213."}, {"id": 2000002351, "trilha": "fiscal", "materia": "adua", "assunto": "Despacho aduaneiro", "tipo": "pergunta", "frente": "O que é despacho aduaneiro de importação?", "verso": "Procedimento pelo qual se verifica a exatidão dos dados declarados pelo importador em relação à mercadoria, aos documentos e à legislação.", "explicacao": "Regulamento Aduaneiro, art. 542."}, {"id": 2000002352, "trilha": "fiscal", "materia": "adua", "assunto": "Despacho aduaneiro", "tipo": "pergunta", "frente": "Qual o documento base do despacho de importação?", "verso": "A declaração de importação (DI), sendo substituída pela Duimp.", "explicacao": ""}, {"id": 2000002353, "trilha": "fiscal", "materia": "adua", "assunto": "Despacho aduaneiro", "tipo": "pergunta", "frente": "Quais são os canais de parametrização no despacho de importação?", "verso": "Verde, amarelo, vermelho e cinza.", "explicacao": "A seleção é feita por análise de risco."}, {"id": 2000002354, "trilha": "fiscal", "materia": "adua", "assunto": "Despacho aduaneiro", "tipo": "pares", "frente": "Canal verde x amarelo x vermelho x cinza.", "verso": "Verde: desembaraço automático, sem exame. Amarelo: exame documental. Vermelho: exame documental e verificação física. Cinza: exame documental, verificação física e procedimento especial de controle (indício de fraude, como subfaturamento).", "explicacao": ""}, {"id": 2000002355, "trilha": "fiscal", "materia": "adua", "assunto": "Despacho aduaneiro", "tipo": "pergunta", "frente": "O que é desembaraço aduaneiro?", "verso": "Ato pelo qual é registrada a conclusão da conferência aduaneira.", "explicacao": "Regulamento Aduaneiro, art. 571."}, {"id": 2000002356, "trilha": "fiscal", "materia": "adua", "assunto": "Despacho aduaneiro", "tipo": "pergunta", "frente": "Mercadoria desembaraçada pode ser revista?", "verso": "Sim, pela revisão aduaneira, para apurar a regularidade do pagamento e do benefício fiscal, enquanto não decaído o direito de constituir o crédito.", "explicacao": "Regulamento Aduaneiro, art. 638."}, {"id": 2000002357, "trilha": "fiscal", "materia": "adua", "assunto": "Despacho aduaneiro", "tipo": "pergunta", "frente": "O que é a entrega antecipada da mercadoria?", "verso": "Autorização para entrega da mercadoria antes do desembaraço, em hipóteses previstas, como mercadorias perecíveis ou de grandes volumes.", "explicacao": ""}, {"id": 2000002358, "trilha": "fiscal", "materia": "adua", "assunto": "Regimes aduaneiros especiais", "tipo": "pergunta", "frente": "O que caracteriza os regimes aduaneiros especiais?", "verso": "Suspensão (ou isenção) dos tributos incidentes, desde que cumpridas as condições do regime.", "explicacao": "Ex.: admissão temporária, drawback, entreposto aduaneiro, trânsito aduaneiro."}, {"id": 2000002359, "trilha": "fiscal", "materia": "adua", "assunto": "Regimes aduaneiros especiais", "tipo": "pergunta", "frente": "O que é o regime de trânsito aduaneiro?", "verso": "Permite transportar mercadoria sob controle aduaneiro de um ponto a outro do território aduaneiro, com suspensão dos tributos.", "explicacao": "Regulamento Aduaneiro, art. 315."}, {"id": 2000002360, "trilha": "fiscal", "materia": "adua", "assunto": "Regimes aduaneiros especiais", "tipo": "pergunta", "frente": "O que é admissão temporária?", "verso": "Permite a importação de bens que devam permanecer no país por prazo fixado, com suspensão total dos tributos, e retornar ao exterior.", "explicacao": "Ex.: bens para feiras, eventos esportivos, exposições."}, {"id": 2000002361, "trilha": "fiscal", "materia": "adua", "assunto": "Regimes aduaneiros especiais", "tipo": "pergunta", "frente": "O que é admissão temporária para utilização econômica?", "verso": "Importação temporária de bens para prestação de serviços ou produção, com pagamento proporcional dos tributos (1% ao mês do tempo de permanência).", "explicacao": ""}, {"id": 2000002362, "trilha": "fiscal", "materia": "adua", "assunto": "Regimes aduaneiros especiais", "tipo": "pergunta", "frente": "O que é exportação temporária?", "verso": "Permite a saída de mercadoria do país com suspensão do imposto de exportação, condicionada ao retorno em prazo determinado, no mesmo estado ou após conserto ou beneficiamento.", "explicacao": ""}, {"id": 2000002363, "trilha": "fiscal", "materia": "adua", "assunto": "Regimes aduaneiros especiais", "tipo": "pergunta", "frente": "O que é drawback?", "verso": "Regime de incentivo à exportação que desonera insumos importados ou adquiridos no país usados na fabricação de produtos exportados.", "explicacao": "Modalidades: suspensão, isenção e restituição."}, {"id": 2000002364, "trilha": "fiscal", "materia": "adua", "assunto": "Regimes aduaneiros especiais", "tipo": "pares", "frente": "Drawback suspensão x isenção x restituição.", "verso": "Suspensão: suspende os tributos na compra de insumos para produto a ser exportado. Isenção: isenta a reposição de insumos já usados em produto exportado. Restituição: devolve os tributos pagos.", "explicacao": ""}, {"id": 2000002365, "trilha": "fiscal", "materia": "adua", "assunto": "Regimes aduaneiros especiais", "tipo": "pergunta", "frente": "O que é entreposto aduaneiro na importação?", "verso": "Permite armazenar mercadoria em recinto alfandegado com suspensão dos tributos.", "explicacao": "Até a nacionalização, reexportação ou outra destinação."}, {"id": 2000002366, "trilha": "fiscal", "materia": "adua", "assunto": "Regimes aduaneiros especiais", "tipo": "pergunta", "frente": "O que é o Recof?", "verso": "Regime de entreposto industrial sob controle informatizado: permite importar insumos com suspensão de tributos para industrialização de produtos exportados ou vendidos no país.", "explicacao": ""}, {"id": 2000002367, "trilha": "fiscal", "materia": "adua", "assunto": "Regimes aduaneiros especiais", "tipo": "pergunta", "frente": "O que é o Repetro?", "verso": "Regime aduaneiro especial para bens destinados à exploração e produção de petróleo e gás natural.", "explicacao": "Repetro-Sped."}, {"id": 2000002368, "trilha": "fiscal", "materia": "adua", "assunto": "Zona Franca", "tipo": "pergunta", "frente": "O que é a Zona Franca de Manaus?", "verso": "Área de livre comércio de importação e exportação e de incentivos fiscais especiais, criada para desenvolver a Amazônia Ocidental.", "explicacao": "Mantida pela CF até 2073 (ADCT, arts. 40 e 92-A)."}, {"id": 2000002369, "trilha": "fiscal", "materia": "adua", "assunto": "Zona Franca", "tipo": "pergunta", "frente": "O que são áreas de livre comércio?", "verso": "Áreas em municípios de fronteira com regime fiscal especial para promover o desenvolvimento regional.", "explicacao": "Ex.: Tabatinga, Macapá-Santana, Guajará-Mirim."}, {"id": 2000002370, "trilha": "fiscal", "materia": "adua", "assunto": "Mercadoria abandonada", "tipo": "pergunta", "frente": "O que acontece com mercadoria que permanece em recinto alfandegado sem despacho após o prazo?", "verso": "É considerada abandonada e fica sujeita à pena de perdimento.", "explicacao": "Prazo, em regra, de 90 dias após a descarga."}, {"id": 2000002371, "trilha": "fiscal", "materia": "adua", "assunto": "Infrações", "tipo": "pergunta", "frente": "O que é a pena de perdimento?", "verso": "Perda da mercadoria (ou do veículo) em favor da União, aplicada nas infrações consideradas dano ao Erário.", "explicacao": "Decreto-Lei 1.455/1976, art. 23."}, {"id": 2000002372, "trilha": "fiscal", "materia": "adua", "assunto": "Infrações", "tipo": "pergunta", "frente": "Se a mercadoria sujeita a perdimento não for encontrada ou tiver sido consumida, o que acontece?", "verso": "A pena de perdimento é convertida em multa equivalente ao valor aduaneiro da mercadoria.", "explicacao": "Decreto-Lei 1.455/1976, art. 23, § 3º."}, {"id": 2000002373, "trilha": "fiscal", "materia": "adua", "assunto": "Infrações", "tipo": "pares", "frente": "Contrabando x descaminho.", "verso": "Contrabando: importar ou exportar mercadoria proibida. Descaminho: iludir, no todo ou em parte, o pagamento de tributo devido pela entrada ou saída de mercadoria permitida.", "explicacao": "CP, arts. 334-A e 334."}, {"id": 2000002374, "trilha": "fiscal", "materia": "adua", "assunto": "Infrações", "tipo": "pergunta", "frente": "Qual o valor do descaminho que permite a aplicação do princípio da insignificância?", "verso": "Até R$ 20.000,00 de tributos iludidos, segundo o STJ e o STF.", "explicacao": "STJ, Tema 157 (revisado em 2018). Em regra, não se aplica em caso de reiteração."}, {"id": 2000002375, "trilha": "fiscal", "materia": "adua", "assunto": "Infrações", "tipo": "pergunta", "frente": "O que é interposição fraudulenta na importação?", "verso": "Ocultação do real vendedor, comprador ou responsável pela operação, mediante fraude ou simulação.", "explicacao": "Dano ao Erário, punido com perdimento."}, {"id": 2000002376, "trilha": "fiscal", "materia": "adua", "assunto": "Infrações", "tipo": "pergunta", "frente": "O que é subfaturamento?", "verso": "Declarar na importação valor inferior ao real, para pagar menos tributos.", "explicacao": ""}, {"id": 2000002377, "trilha": "fiscal", "materia": "adua", "assunto": "Tributos na importação", "tipo": "pergunta", "frente": "Quais tributos federais incidem normalmente na importação?", "verso": "II, IPI-importação, PIS/Pasep-importação, Cofins-importação, e CIDE-combustíveis quando aplicável.", "explicacao": "Além do ICMS estadual e da AFRMM no transporte marítimo."}, {"id": 2000002378, "trilha": "fiscal", "materia": "adua", "assunto": "Tributos na importação", "tipo": "pergunta", "frente": "Qual a base de cálculo do IPI na importação?", "verso": "Valor aduaneiro acrescido do II e dos encargos cambiais.", "explicacao": "CTN, art. 47, I."}, {"id": 2000002379, "trilha": "fiscal", "materia": "adua", "assunto": "Tributos na importação", "tipo": "pergunta", "frente": "Qual a base de cálculo do PIS e da Cofins-importação?", "verso": "O valor aduaneiro.", "explicacao": "STF, RE 559.937, afastou a inclusão do ICMS e das próprias contribuições na base."}, {"id": 2000002380, "trilha": "fiscal", "materia": "adua", "assunto": "Tributos na importação", "tipo": "pergunta", "frente": "O que é o AFRMM?", "verso": "Adicional ao Frete para Renovação da Marinha Mercante, cobrado sobre o frete do transporte aquaviário de carga.", "explicacao": "Lei 10.893/2004."}, {"id": 2000002381, "trilha": "fiscal", "materia": "adua", "assunto": "Comércio exterior", "tipo": "pergunta", "frente": "O que é o Operador Econômico Autorizado (OEA)?", "verso": "Programa que certifica empresas de baixo risco na cadeia logística, dando a elas agilidade e previsibilidade no controle aduaneiro.", "explicacao": "Baseado no SAFE Framework da Organização Mundial das Aduanas."}, {"id": 2000002382, "trilha": "fiscal", "materia": "adua", "assunto": "Comércio exterior", "tipo": "pergunta", "frente": "O que são Incoterms?", "verso": "Termos internacionais de comércio que definem obrigações, custos e riscos entre vendedor e comprador.", "explicacao": "Publicados pela Câmara de Comércio Internacional."}, {"id": 2000002383, "trilha": "fiscal", "materia": "adua", "assunto": "Comércio exterior", "tipo": "pares", "frente": "Incoterm FOB x CIF.", "verso": "FOB: o vendedor entrega a mercadoria a bordo do navio no porto de embarque; frete e seguro principal são do comprador. CIF: o vendedor paga custo, seguro e frete até o porto de destino; o risco passa a bordo, no embarque.", "explicacao": "Ambos são marítimos."}, {"id": 2000002384, "trilha": "fiscal", "materia": "adua", "assunto": "Comércio exterior", "tipo": "pergunta", "frente": "O que é o Incoterm EXW?", "verso": "Ex Works: o vendedor coloca a mercadoria à disposição no seu estabelecimento; o comprador assume todos os custos e riscos a partir daí.", "explicacao": "Máxima obrigação do comprador."}, {"id": 2000002385, "trilha": "fiscal", "materia": "adua", "assunto": "Comércio exterior", "tipo": "pergunta", "frente": "O que é o Incoterm DDP?", "verso": "Delivered Duty Paid: o vendedor entrega a mercadoria no destino, com tributos de importação pagos.", "explicacao": "Máxima obrigação do vendedor."}, {"id": 2000002386, "trilha": "fiscal", "materia": "adua", "assunto": "Comércio exterior", "tipo": "pergunta", "frente": "O que é dumping?", "verso": "Exportar produto a preço inferior ao valor normal praticado no mercado interno do país exportador, causando dano à indústria do país importador.", "explicacao": "Combatido com direitos antidumping."}, {"id": 2000002387, "trilha": "fiscal", "materia": "adua", "assunto": "Comércio exterior", "tipo": "pares", "frente": "Direito antidumping x medida compensatória x salvaguarda.", "verso": "Antidumping: contra preços abaixo do valor normal. Compensatória: contra subsídios do país exportador. Salvaguarda: proteção temporária contra surto de importações, mesmo sem prática desleal.", "explicacao": "Defesa comercial."}, {"id": 2000002388, "trilha": "fiscal", "materia": "adua", "assunto": "Comércio exterior", "tipo": "pergunta", "frente": "O que é a cláusula da nação mais favorecida (OMC)?", "verso": "Vantagem concedida a um país deve ser estendida a todos os membros da OMC.", "explicacao": "Exceções: acordos regionais como o Mercosul."}, {"id": 2000002389, "trilha": "fiscal", "materia": "adua", "assunto": "Comércio exterior", "tipo": "pergunta", "frente": "Qual o órgão anuente em licenciamento de importações de medicamentos e alimentos?", "verso": "A Anvisa.", "explicacao": "Outros: Mapa (produtos agropecuários), Ibama, Exército."}, {"id": 2000002390, "trilha": "fiscal", "materia": "adua", "assunto": "Bagagem", "tipo": "pergunta", "frente": "O que é bagagem para fins aduaneiros?", "verso": "Bens novos ou usados que o viajante, em compatibilidade com as circunstâncias da viagem, puder destinar ao uso ou consumo pessoal, bem como para presentear.", "explicacao": "Bens com destinação comercial não são bagagem."}, {"id": 2000002391, "trilha": "fiscal", "materia": "est", "assunto": "Conceitos", "tipo": "pares", "frente": "Estatística descritiva x inferencial.", "verso": "Descritiva: organiza e resume dados (tabelas, gráficos, medidas). Inferencial: tira conclusões sobre a população a partir da amostra, com margem de erro.", "explicacao": ""}, {"id": 2000002392, "trilha": "fiscal", "materia": "est", "assunto": "Conceitos", "tipo": "pares", "frente": "Variável quantitativa discreta x contínua.", "verso": "Discreta: valores contáveis, geralmente inteiros (número de filhos). Contínua: qualquer valor num intervalo (altura, peso, tempo).", "explicacao": ""}, {"id": 2000002393, "trilha": "fiscal", "materia": "est", "assunto": "Conceitos", "tipo": "pares", "frente": "Variável qualitativa nominal x ordinal.", "verso": "Nominal: categorias sem ordem (cor dos olhos, sexo). Ordinal: categorias com ordem (escolaridade, classe social).", "explicacao": ""}, {"id": 2000002394, "trilha": "fiscal", "materia": "est", "assunto": "Conceitos", "tipo": "pares", "frente": "Parâmetro x estatística (estimador).", "verso": "Parâmetro: medida da população (μ, σ). Estatística: medida calculada na amostra (x̄, s), usada para estimar o parâmetro.", "explicacao": ""}, {"id": 2000002395, "trilha": "fiscal", "materia": "est", "assunto": "Distribuição de frequências", "tipo": "pares", "frente": "Frequência absoluta x relativa x acumulada.", "verso": "Absoluta: quantas vezes o valor aparece. Relativa: absoluta ÷ total (proporção). Acumulada: soma das frequências até aquela classe.", "explicacao": ""}, {"id": 2000002396, "trilha": "fiscal", "materia": "est", "assunto": "Distribuição de frequências", "tipo": "pergunta", "frente": "Como se calcula o ponto médio de uma classe?", "verso": "(Limite inferior + limite superior) ÷ 2.", "explicacao": "Usado para calcular a média de dados agrupados."}, {"id": 2000002397, "trilha": "fiscal", "materia": "est", "assunto": "Distribuição de frequências", "tipo": "pergunta", "frente": "O que é um histograma?", "verso": "Gráfico de barras justapostas que representa a distribuição de frequências de uma variável contínua agrupada em classes.", "explicacao": "O polígono de frequências liga os pontos médios do topo das barras."}, {"id": 2000002398, "trilha": "fiscal", "materia": "est", "assunto": "Distribuição de frequências", "tipo": "pergunta", "frente": "O que mostra um boxplot?", "verso": "Mediana, quartis, amplitude interquartil e possíveis valores discrepantes (outliers).", "explicacao": "Diagrama de caixa."}, {"id": 2000002399, "trilha": "fiscal", "materia": "est", "assunto": "Medidas de posição", "tipo": "pergunta", "frente": "Qual medida de tendência central é mais afetada por valores extremos?", "verso": "A média.", "explicacao": "A mediana é robusta a valores extremos."}, {"id": 2000002400, "trilha": "fiscal", "materia": "est", "assunto": "Medidas de posição", "tipo": "pergunta", "frente": "Se somarmos 10 a todos os valores de um conjunto, o que acontece com a média?", "verso": "Aumenta 10.", "explicacao": "Multiplicar todos por k multiplica a média por k."}, {"id": 2000002401, "trilha": "fiscal", "materia": "est", "assunto": "Medidas de posição", "tipo": "pergunta", "frente": "Qual a soma dos desvios dos valores em relação à média?", "verso": "Zero.", "explicacao": "Propriedade da média aritmética."}, {"id": 2000002402, "trilha": "fiscal", "materia": "est", "assunto": "Medidas de posição", "tipo": "pergunta", "frente": "O que são quartis?", "verso": "Valores que dividem o conjunto ordenado em quatro partes iguais: Q1 (25%), Q2 (50%, a mediana) e Q3 (75%).", "explicacao": "Decis dividem em 10 partes; percentis, em 100."}, {"id": 2000002403, "trilha": "fiscal", "materia": "est", "assunto": "Medidas de posição", "tipo": "pergunta", "frente": "O que é a média geométrica e quando se usa?", "verso": "Raiz n-ésima do produto de n valores; usada para taxas de crescimento médias.", "explicacao": "Média harmônica: para velocidades médias com distâncias iguais."}, {"id": 2000002404, "trilha": "fiscal", "materia": "est", "assunto": "Medidas de posição", "tipo": "pergunta", "frente": "Qual a relação entre médias aritmética, geométrica e harmônica de valores positivos?", "verso": "Aritmética ≥ geométrica ≥ harmônica.", "explicacao": "Iguais apenas se todos os valores forem iguais."}, {"id": 2000002405, "trilha": "fiscal", "materia": "est", "assunto": "Medidas de posição", "tipo": "pergunta", "frente": "Um conjunto pode ter mais de uma moda?", "verso": "Sim: bimodal, multimodal; ou nenhuma moda (amodal).", "explicacao": ""}, {"id": 2000002406, "trilha": "fiscal", "materia": "est", "assunto": "Medidas de dispersão", "tipo": "pergunta", "frente": "Como se calcula a variância populacional?", "verso": "Média dos quadrados dos desvios em relação à média: σ² = Σ(x − μ)² ÷ N.", "explicacao": "Na amostral, divide-se por n − 1."}, {"id": 2000002407, "trilha": "fiscal", "materia": "est", "assunto": "Medidas de dispersão", "tipo": "pergunta", "frente": "Por que a variância amostral divide por n − 1?", "verso": "Para que seja um estimador não viesado da variância populacional.", "explicacao": "Correção de Bessel."}, {"id": 2000002408, "trilha": "fiscal", "materia": "est", "assunto": "Medidas de dispersão", "tipo": "pergunta", "frente": "Se multiplicarmos todos os valores por 3, o que acontece com a variância e o desvio padrão?", "verso": "A variância fica multiplicada por 9 e o desvio padrão por 3.", "explicacao": "Somar constante não altera nenhum dos dois."}, {"id": 2000002409, "trilha": "fiscal", "materia": "est", "assunto": "Medidas de dispersão", "tipo": "pergunta", "frente": "O que é a amplitude interquartil?", "verso": "Q3 − Q1: mede a dispersão dos 50% centrais dos dados.", "explicacao": "Usada para identificar outliers."}, {"id": 2000002410, "trilha": "fiscal", "materia": "est", "assunto": "Medidas de dispersão", "tipo": "pergunta", "frente": "Qual a unidade da variância?", "verso": "O quadrado da unidade dos dados.", "explicacao": "Por isso se usa o desvio padrão, na mesma unidade dos dados."}, {"id": 2000002411, "trilha": "fiscal", "materia": "est", "assunto": "Assimetria", "tipo": "pares", "frente": "Assimetria positiva x negativa.", "verso": "Positiva (à direita): cauda longa à direita; média > mediana > moda. Negativa (à esquerda): cauda à esquerda; média < mediana < moda.", "explicacao": "Na simétrica, as três coincidem."}, {"id": 2000002412, "trilha": "fiscal", "materia": "est", "assunto": "Curtose", "tipo": "pares", "frente": "Distribuição leptocúrtica x mesocúrtica x platicúrtica.", "verso": "Leptocúrtica: mais concentrada e afilada que a normal. Mesocúrtica: semelhante à normal. Platicúrtica: mais achatada.", "explicacao": ""}, {"id": 2000002413, "trilha": "fiscal", "materia": "est", "assunto": "Probabilidade", "tipo": "pergunta", "frente": "Como se calcula a probabilidade condicional P(A|B)?", "verso": "P(A e B) ÷ P(B).", "explicacao": ""}, {"id": 2000002414, "trilha": "fiscal", "materia": "est", "assunto": "Probabilidade", "tipo": "pergunta", "frente": "Quando dois eventos são independentes?", "verso": "Quando P(A e B) = P(A) · P(B), ou seja, a ocorrência de um não altera a probabilidade do outro.", "explicacao": ""}, {"id": 2000002415, "trilha": "fiscal", "materia": "est", "assunto": "Probabilidade", "tipo": "pares", "frente": "Eventos mutuamente exclusivos x independentes.", "verso": "Mutuamente exclusivos: não podem ocorrer juntos (P(A e B) = 0). Independentes: um não afeta o outro. Eventos com probabilidade positiva não podem ser as duas coisas ao mesmo tempo.", "explicacao": ""}, {"id": 2000002416, "trilha": "fiscal", "materia": "est", "assunto": "Probabilidade", "tipo": "pergunta", "frente": "Para que serve o teorema de Bayes?", "verso": "Calcular a probabilidade de uma causa dado que se observou um efeito: P(A|B) = P(B|A)·P(A) ÷ P(B).", "explicacao": "Clássico em questões de testes diagnósticos."}, {"id": 2000002417, "trilha": "fiscal", "materia": "est", "assunto": "Probabilidade", "tipo": "pergunta", "frente": "O que é o teorema da probabilidade total?", "verso": "P(B) = Σ P(B|Aᵢ)·P(Aᵢ), somando sobre uma partição de eventos Aᵢ.", "explicacao": ""}, {"id": 2000002418, "trilha": "fiscal", "materia": "est", "assunto": "Variáveis aleatórias", "tipo": "pergunta", "frente": "O que é esperança (valor esperado) de uma variável aleatória discreta?", "verso": "Soma de cada valor multiplicado por sua probabilidade: E(X) = Σ x·P(x).", "explicacao": ""}, {"id": 2000002419, "trilha": "fiscal", "materia": "est", "assunto": "Variáveis aleatórias", "tipo": "pergunta", "frente": "Quais as propriedades da esperança para uma transformação aX + b?", "verso": "E(aX + b) = a·E(X) + b e Var(aX + b) = a²·Var(X).", "explicacao": ""}, {"id": 2000002420, "trilha": "fiscal", "materia": "est", "assunto": "Variáveis aleatórias", "tipo": "pergunta", "frente": "Qual a variância da soma de duas variáveis independentes?", "verso": "Var(X + Y) = Var(X) + Var(Y).", "explicacao": "Se não forem independentes, soma-se 2·Cov(X,Y)."}, {"id": 2000002421, "trilha": "fiscal", "materia": "est", "assunto": "Distribuições", "tipo": "pergunta", "frente": "Quando se usa a distribuição binomial?", "verso": "Para contar sucessos em n tentativas independentes, cada uma com probabilidade p de sucesso.", "explicacao": "Média np; variância np(1 − p)."}, {"id": 2000002422, "trilha": "fiscal", "materia": "est", "assunto": "Distribuições", "tipo": "pergunta", "frente": "Quando se usa a distribuição de Poisson?", "verso": "Para contar ocorrências de eventos raros num intervalo de tempo ou espaço, com taxa média λ.", "explicacao": "Média e variância iguais a λ."}, {"id": 2000002423, "trilha": "fiscal", "materia": "est", "assunto": "Distribuições", "tipo": "pergunta", "frente": "Quais as características da distribuição normal?", "verso": "Simétrica, em forma de sino, definida pela média e pelo desvio padrão; média, mediana e moda coincidem.", "explicacao": ""}, {"id": 2000002424, "trilha": "fiscal", "materia": "est", "assunto": "Distribuições", "tipo": "pergunta", "frente": "Na normal, que percentual dos dados fica a 1, 2 e 3 desvios padrão da média?", "verso": "Cerca de 68%, 95% e 99,7%.", "explicacao": "Regra empírica."}, {"id": 2000002425, "trilha": "fiscal", "materia": "est", "assunto": "Distribuições", "tipo": "pergunta", "frente": "Como se padroniza uma variável normal?", "verso": "Z = (X − μ) ÷ σ, obtendo a normal padrão (média 0 e desvio padrão 1).", "explicacao": ""}, {"id": 2000002426, "trilha": "fiscal", "materia": "est", "assunto": "Distribuições", "tipo": "pergunta", "frente": "Quando se usa a distribuição t de Student?", "verso": "Para inferência sobre a média quando a variância populacional é desconhecida e a amostra é pequena.", "explicacao": "Tem caudas mais pesadas que a normal; aproxima-se dela com n grande."}, {"id": 2000002427, "trilha": "fiscal", "materia": "est", "assunto": "Distribuições", "tipo": "pergunta", "frente": "Para que se usa a distribuição qui-quadrado?", "verso": "Em testes de aderência, de independência em tabelas de contingência e inferência sobre a variância.", "explicacao": ""}, {"id": 2000002428, "trilha": "fiscal", "materia": "est", "assunto": "Distribuições", "tipo": "pergunta", "frente": "O que diz o Teorema Central do Limite?", "verso": "Para amostras grandes, a distribuição da média amostral se aproxima da normal, qualquer que seja a distribuição da população.", "explicacao": "Desvio padrão da média amostral: σ ÷ √n (erro padrão)."}, {"id": 2000002429, "trilha": "fiscal", "materia": "est", "assunto": "Amostragem", "tipo": "pares", "frente": "Amostragem estratificada x por conglomerados.", "verso": "Estratificada: divide a população em estratos homogêneos internamente e sorteia em todos. Conglomerados: divide em grupos heterogêneos internamente e sorteia alguns grupos inteiros.", "explicacao": ""}, {"id": 2000002430, "trilha": "fiscal", "materia": "est", "assunto": "Amostragem", "tipo": "pergunta", "frente": "O que é amostragem sistemática?", "verso": "Seleciona elementos em intervalos fixos a partir de um ponto inicial sorteado (ex.: a cada 10º da lista).", "explicacao": ""}, {"id": 2000002431, "trilha": "fiscal", "materia": "est", "assunto": "Amostragem", "tipo": "pergunta", "frente": "O que é amostragem por conveniência?", "verso": "Seleção não probabilística de elementos de fácil acesso.", "explicacao": "Não permite inferências estatísticas confiáveis."}, {"id": 2000002432, "trilha": "fiscal", "materia": "est", "assunto": "Inferência", "tipo": "pergunta", "frente": "O que é intervalo de confiança de 95%?", "verso": "Intervalo construído por um método que, em repetidas amostras, contém o parâmetro verdadeiro em 95% das vezes.", "explicacao": ""}, {"id": 2000002433, "trilha": "fiscal", "materia": "est", "assunto": "Inferência", "tipo": "pergunta", "frente": "O que acontece com a amplitude do intervalo de confiança quando aumenta o tamanho da amostra?", "verso": "Diminui (fica mais preciso).", "explicacao": "Aumentar o nível de confiança aumenta a amplitude."}, {"id": 2000002434, "trilha": "fiscal", "materia": "est", "assunto": "Inferência", "tipo": "pergunta", "frente": "Como calcular o intervalo de confiança para a média com σ conhecido?", "verso": "x̄ ± z · σ ÷ √n.", "explicacao": "Para 95%, z ≈ 1,96."}, {"id": 2000002435, "trilha": "fiscal", "materia": "est", "assunto": "Inferência", "tipo": "pergunta", "frente": "Para reduzir pela metade o erro amostral, o que é preciso fazer com o tamanho da amostra?", "verso": "Quadruplicá-lo.", "explicacao": "O erro é proporcional a 1 ÷ √n."}, {"id": 2000002436, "trilha": "fiscal", "materia": "est", "assunto": "Inferência", "tipo": "pares", "frente": "Estimador não viesado x consistente.", "verso": "Não viesado: seu valor esperado é igual ao parâmetro. Consistente: converge para o parâmetro quando n cresce.", "explicacao": ""}, {"id": 2000002437, "trilha": "fiscal", "materia": "est", "assunto": "Testes de hipóteses", "tipo": "pares", "frente": "Hipótese nula x alternativa.", "verso": "Nula (H₀): afirmação de igualdade ou ausência de efeito, testada. Alternativa (H₁): o que se aceita se H₀ for rejeitada.", "explicacao": ""}, {"id": 2000002438, "trilha": "fiscal", "materia": "est", "assunto": "Testes de hipóteses", "tipo": "pares", "frente": "Erro tipo I x erro tipo II.", "verso": "Tipo I: rejeitar H₀ verdadeira (probabilidade α, nível de significância). Tipo II: não rejeitar H₀ falsa (probabilidade β).", "explicacao": "Poder do teste = 1 − β."}, {"id": 2000002439, "trilha": "fiscal", "materia": "est", "assunto": "Testes de hipóteses", "tipo": "pergunta", "frente": "O que é o p-valor?", "verso": "A probabilidade de obter um resultado tão ou mais extremo que o observado, supondo H₀ verdadeira.", "explicacao": "Rejeita-se H₀ se p-valor < α."}, {"id": 2000002440, "trilha": "fiscal", "materia": "est", "assunto": "Testes de hipóteses", "tipo": "pares", "frente": "Teste unilateral x bilateral.", "verso": "Unilateral: H₁ indica uma direção (maior ou menor). Bilateral: H₁ indica apenas diferença (≠), e α é dividido entre as duas caudas.", "explicacao": ""}, {"id": 2000002441, "trilha": "fiscal", "materia": "est", "assunto": "Correlação e regressão", "tipo": "pergunta", "frente": "O que indica o coeficiente de correlação de Pearson?", "verso": "A força e o sentido da relação linear entre duas variáveis, de −1 a +1.", "explicacao": "Zero indica ausência de relação linear (pode haver relação não linear)."}, {"id": 2000002442, "trilha": "fiscal", "materia": "est", "assunto": "Correlação e regressão", "tipo": "certo_errado", "frente": "Certo ou errado? Correlação alta prova causalidade.", "verso": "Errado. Correlação não implica causalidade.", "explicacao": "Pode haver variável de confusão."}, {"id": 2000002443, "trilha": "fiscal", "materia": "est", "assunto": "Correlação e regressão", "tipo": "pergunta", "frente": "O que é o coeficiente de determinação R²?", "verso": "Proporção da variação da variável dependente explicada pelo modelo de regressão.", "explicacao": "Na regressão simples, é o quadrado do coeficiente de correlação."}, {"id": 2000002444, "trilha": "fiscal", "materia": "est", "assunto": "Correlação e regressão", "tipo": "pergunta", "frente": "No modelo y = a + bx, o que representa b?", "verso": "A variação média de y para cada aumento de uma unidade em x.", "explicacao": "Estimado por mínimos quadrados."}, {"id": 2000002445, "trilha": "fiscal", "materia": "est", "assunto": "Correlação e regressão", "tipo": "pergunta", "frente": "O que faz o método dos mínimos quadrados?", "verso": "Encontra a reta que minimiza a soma dos quadrados dos resíduos (diferença entre valores observados e previstos).", "explicacao": ""}, {"id": 2000002446, "trilha": "fiscal", "materia": "est", "assunto": "Correlação e regressão", "tipo": "pergunta", "frente": "O que é multicolinearidade?", "verso": "Alta correlação entre variáveis explicativas de um modelo de regressão, que dificulta estimar o efeito de cada uma.", "explicacao": ""}, {"id": 2000002447, "trilha": "fiscal", "materia": "est", "assunto": "Correlação e regressão", "tipo": "pergunta", "frente": "O que é covariância?", "verso": "Medida de como duas variáveis variam juntas: positiva se crescem juntas, negativa se uma cresce quando a outra cai.", "explicacao": "Correlação = covariância ÷ (σx · σy)."}, {"id": 2000002448, "trilha": "fiscal", "materia": "est", "assunto": "Números-índice", "tipo": "pergunta", "frente": "O que é um número-índice?", "verso": "Medida que compara a variação de uma grandeza entre dois momentos, em relação a uma base (geralmente 100).", "explicacao": "Ex.: IPCA."}, {"id": 2000002449, "trilha": "fiscal", "materia": "est", "assunto": "Números-índice", "tipo": "pares", "frente": "Índice de Laspeyres x Paasche.", "verso": "Laspeyres: ponderado pelas quantidades do período-base. Paasche: ponderado pelas quantidades do período atual.", "explicacao": "Índice de Fisher: média geométrica dos dois."}, {"id": 2000002450, "trilha": "fiscal", "materia": "est", "assunto": "Séries temporais", "tipo": "pergunta", "frente": "Quais os componentes de uma série temporal?", "verso": "Tendência, sazonalidade, ciclo e componente aleatório (irregular).", "explicacao": ""}, {"id": 2000002451, "trilha": "fiscal", "materia": "dados", "assunto": "Conceitos", "tipo": "pares", "frente": "Dado x informação x conhecimento.", "verso": "Dado: registro bruto, sem contexto. Informação: dado organizado e contextualizado, com significado. Conhecimento: informação interpretada e aplicada à tomada de decisão.", "explicacao": "Pirâmide DIKW (dados, informação, conhecimento, sabedoria)."}, {"id": 2000002452, "trilha": "fiscal", "materia": "dados", "assunto": "Conceitos", "tipo": "pares", "frente": "Dados estruturados x semiestruturados x não estruturados.", "verso": "Estruturados: formato fixo de linhas e colunas (tabelas de banco relacional). Semiestruturados: têm marcações mas não esquema rígido (JSON, XML). Não estruturados: sem formato predefinido (textos livres, imagens, vídeos, áudios).", "explicacao": ""}, {"id": 2000002453, "trilha": "fiscal", "materia": "dados", "assunto": "Conceitos", "tipo": "pergunta", "frente": "Quais são os “Vs” clássicos do big data?", "verso": "Volume, velocidade e variedade; somam-se veracidade e valor.", "explicacao": ""}, {"id": 2000002454, "trilha": "fiscal", "materia": "dados", "assunto": "Conceitos", "tipo": "pergunta", "frente": "O que é ciência de dados?", "verso": "Área que usa estatística, programação e conhecimento do negócio para extrair conhecimento e valor de dados.", "explicacao": ""}, {"id": 2000002455, "trilha": "fiscal", "materia": "dados", "assunto": "Conceitos", "tipo": "pergunta", "frente": "O que é a tomada de decisão orientada por dados (data-driven)?", "verso": "Basear decisões em evidências obtidas da análise de dados, e não apenas em intuição ou experiência.", "explicacao": ""}, {"id": 2000002456, "trilha": "fiscal", "materia": "dados", "assunto": "Bancos de dados", "tipo": "pergunta", "frente": "O que é um SGBD?", "verso": "Sistema Gerenciador de Banco de Dados: software que armazena, organiza e controla o acesso aos dados.", "explicacao": "Ex.: PostgreSQL, Oracle, MySQL, SQL Server."}, {"id": 2000002457, "trilha": "fiscal", "materia": "dados", "assunto": "Bancos de dados", "tipo": "pares", "frente": "Chave primária x chave estrangeira.", "verso": "Primária: identifica de forma única cada registro da tabela (não repete nem é nula). Estrangeira: campo que referencia a chave primária de outra tabela, criando relacionamento.", "explicacao": ""}, {"id": 2000002458, "trilha": "fiscal", "materia": "dados", "assunto": "Bancos de dados", "tipo": "pergunta", "frente": "O que são as propriedades ACID das transações?", "verso": "Atomicidade, consistência, isolamento e durabilidade.", "explicacao": "Garantem a confiabilidade em bancos relacionais."}, {"id": 2000002459, "trilha": "fiscal", "materia": "dados", "assunto": "Bancos de dados", "tipo": "pergunta", "frente": "O que é normalização de banco de dados?", "verso": "Organizar as tabelas para reduzir redundâncias e anomalias de inserção, atualização e exclusão (1FN, 2FN, 3FN...).", "explicacao": ""}, {"id": 2000002460, "trilha": "fiscal", "materia": "dados", "assunto": "Bancos de dados", "tipo": "pares", "frente": "Banco relacional x NoSQL.", "verso": "Relacional: tabelas com esquema fixo e linguagem SQL. NoSQL: modelos flexíveis (documentos, chave-valor, colunas, grafos), escaláveis para grandes volumes.", "explicacao": "MongoDB (documentos), Redis (chave-valor), Neo4j (grafos)."}, {"id": 2000002461, "trilha": "fiscal", "materia": "dados", "assunto": "SQL", "tipo": "pergunta", "frente": "Qual comando SQL consulta dados?", "verso": "SELECT.", "explicacao": "SELECT colunas FROM tabela WHERE condição."}, {"id": 2000002462, "trilha": "fiscal", "materia": "dados", "assunto": "SQL", "tipo": "pares", "frente": "DDL x DML.", "verso": "DDL (definição): CREATE, ALTER, DROP — estrutura. DML (manipulação): INSERT, UPDATE, DELETE, SELECT — dados.", "explicacao": "DCL: GRANT e REVOKE (permissões)."}, {"id": 2000002463, "trilha": "fiscal", "materia": "dados", "assunto": "SQL", "tipo": "pares", "frente": "WHERE x HAVING.", "verso": "WHERE: filtra linhas antes do agrupamento. HAVING: filtra grupos depois do GROUP BY, podendo usar funções de agregação.", "explicacao": ""}, {"id": 2000002464, "trilha": "fiscal", "materia": "dados", "assunto": "SQL", "tipo": "pergunta", "frente": "Para que serve o GROUP BY?", "verso": "Agrupar linhas com valores iguais para aplicar funções de agregação (COUNT, SUM, AVG, MAX, MIN).", "explicacao": ""}, {"id": 2000002465, "trilha": "fiscal", "materia": "dados", "assunto": "SQL", "tipo": "pares", "frente": "INNER JOIN x LEFT JOIN.", "verso": "INNER: retorna apenas os registros com correspondência nas duas tabelas. LEFT: retorna todos os da tabela da esquerda, com nulos onde não houver correspondência.", "explicacao": ""}, {"id": 2000002466, "trilha": "fiscal", "materia": "dados", "assunto": "SQL", "tipo": "pares", "frente": "DELETE x TRUNCATE x DROP.", "verso": "DELETE: remove linhas (pode usar WHERE). TRUNCATE: remove todas as linhas, mantendo a estrutura. DROP: remove a tabela inteira.", "explicacao": ""}, {"id": 2000002467, "trilha": "fiscal", "materia": "dados", "assunto": "SQL", "tipo": "pergunta", "frente": "Para que serve o DISTINCT?", "verso": "Eliminar valores duplicados no resultado da consulta.", "explicacao": ""}, {"id": 2000002468, "trilha": "fiscal", "materia": "dados", "assunto": "SQL", "tipo": "pergunta", "frente": "O que retorna COUNT(*) e COUNT(coluna)?", "verso": "COUNT(*): todas as linhas. COUNT(coluna): apenas as linhas em que a coluna não é nula.", "explicacao": ""}, {"id": 2000002469, "trilha": "fiscal", "materia": "dados", "assunto": "Data warehouse", "tipo": "pergunta", "frente": "O que é data warehouse?", "verso": "Repositório integrado, orientado a assuntos, histórico e não volátil, usado para análise e apoio à decisão.", "explicacao": "Definição de Bill Inmon."}, {"id": 2000002470, "trilha": "fiscal", "materia": "dados", "assunto": "Data warehouse", "tipo": "pares", "frente": "OLTP x OLAP.", "verso": "OLTP: sistemas transacionais do dia a dia (muitas inserções e atualizações). OLAP: processamento analítico de grandes volumes, para consultas e relatórios.", "explicacao": ""}, {"id": 2000002471, "trilha": "fiscal", "materia": "dados", "assunto": "Data warehouse", "tipo": "pergunta", "frente": "O que é ETL?", "verso": "Extração, transformação e carga de dados das fontes para o data warehouse.", "explicacao": "No ELT, carrega-se antes de transformar."}, {"id": 2000002472, "trilha": "fiscal", "materia": "dados", "assunto": "Data warehouse", "tipo": "pares", "frente": "Data warehouse x data lake.", "verso": "Data warehouse: dados estruturados e tratados, com esquema definido na gravação. Data lake: dados brutos de qualquer formato, com esquema definido na leitura.", "explicacao": ""}, {"id": 2000002473, "trilha": "fiscal", "materia": "dados", "assunto": "Data warehouse", "tipo": "pares", "frente": "Tabela fato x tabela dimensão.", "verso": "Fato: medidas numéricas do negócio (valor da venda, quantidade). Dimensão: contexto descritivo (cliente, produto, tempo, local).", "explicacao": "Modelo estrela e floco de neve."}, {"id": 2000002474, "trilha": "fiscal", "materia": "dados", "assunto": "Data warehouse", "tipo": "pergunta", "frente": "O que é data mart?", "verso": "Subconjunto do data warehouse voltado a uma área específica (vendas, finanças).", "explicacao": ""}, {"id": 2000002475, "trilha": "fiscal", "materia": "dados", "assunto": "Data warehouse", "tipo": "pares", "frente": "Drill down x roll up.", "verso": "Drill down: navegar do resumo para o detalhe (ano → mês → dia). Roll up: agregar do detalhe para o resumo.", "explicacao": "Operações OLAP. Slice e dice filtram dimensões."}, {"id": 2000002476, "trilha": "fiscal", "materia": "dados", "assunto": "Qualidade de dados", "tipo": "pergunta", "frente": "Quais as dimensões da qualidade de dados?", "verso": "Completude, exatidão (acurácia), consistência, atualidade (tempestividade), validade e unicidade.", "explicacao": ""}, {"id": 2000002477, "trilha": "fiscal", "materia": "dados", "assunto": "Qualidade de dados", "tipo": "pergunta", "frente": "O que é limpeza de dados?", "verso": "Corrigir ou remover dados incorretos, duplicados, incompletos ou fora do padrão antes da análise.", "explicacao": ""}, {"id": 2000002478, "trilha": "fiscal", "materia": "dados", "assunto": "Qualidade de dados", "tipo": "pergunta", "frente": "O que é um outlier?", "verso": "Valor muito distante dos demais, que pode ser erro de registro ou um caso real atípico.", "explicacao": "Deve ser investigado, não removido automaticamente."}, {"id": 2000002479, "trilha": "fiscal", "materia": "dados", "assunto": "Governança", "tipo": "pergunta", "frente": "O que é governança de dados?", "verso": "Conjunto de políticas, papéis, processos e padrões para garantir a qualidade, segurança e uso adequado dos dados.", "explicacao": "DAMA-DMBOK é o principal referencial."}, {"id": 2000002480, "trilha": "fiscal", "materia": "dados", "assunto": "Governança", "tipo": "pares", "frente": "Dono dos dados (data owner) x curador (data steward).", "verso": "Owner: responsável pela área de negócio que define regras e acesso. Steward: cuida da qualidade, das definições e do uso no dia a dia.", "explicacao": ""}, {"id": 2000002481, "trilha": "fiscal", "materia": "dados", "assunto": "Governança", "tipo": "pergunta", "frente": "O que são metadados?", "verso": "Dados sobre os dados: origem, formato, significado, data de criação, responsável.", "explicacao": ""}, {"id": 2000002482, "trilha": "fiscal", "materia": "dados", "assunto": "Governança", "tipo": "pergunta", "frente": "O que são dados abertos?", "verso": "Dados públicos disponíveis na internet, em formato aberto e legível por máquina, que podem ser usados livremente.", "explicacao": "Portal dados.gov.br; Decreto 8.777/2016."}, {"id": 2000002483, "trilha": "fiscal", "materia": "dados", "assunto": "LGPD", "tipo": "pergunta", "frente": "Qual o objetivo da LGPD?", "verso": "Proteger os direitos de liberdade e privacidade no tratamento de dados pessoais, inclusive em meios digitais.", "explicacao": "Lei 13.709/2018."}, {"id": 2000002484, "trilha": "fiscal", "materia": "dados", "assunto": "LGPD", "tipo": "pares", "frente": "Dado pessoal x dado pessoal sensível x dado anonimizado.", "verso": "Pessoal: relacionado a pessoa identificada ou identificável. Sensível: origem racial, convicção religiosa, opinião política, saúde, vida sexual, genético ou biométrico, entre outros. Anonimizado: não permite identificar o titular; não é dado pessoal para a LGPD.", "explicacao": "LGPD, art. 5º."}, {"id": 2000002485, "trilha": "fiscal", "materia": "dados", "assunto": "LGPD", "tipo": "pares", "frente": "Controlador x operador x encarregado.", "verso": "Controlador: decide sobre o tratamento. Operador: trata os dados em nome do controlador. Encarregado (DPO): canal de comunicação com titulares e a ANPD.", "explicacao": "LGPD, art. 5º."}, {"id": 2000002486, "trilha": "fiscal", "materia": "dados", "assunto": "LGPD", "tipo": "pergunta", "frente": "Cite bases legais para tratamento de dados pessoais.", "verso": "Consentimento, cumprimento de obrigação legal, execução de políticas públicas, estudos por órgão de pesquisa, execução de contrato, exercício de direitos, proteção da vida, tutela da saúde, legítimo interesse e proteção do crédito.", "explicacao": "LGPD, art. 7º."}, {"id": 2000002487, "trilha": "fiscal", "materia": "dados", "assunto": "LGPD", "tipo": "pergunta", "frente": "O poder público precisa de consentimento para tratar dados na execução de políticas públicas?", "verso": "Não. A execução de políticas públicas é base legal própria.", "explicacao": "LGPD, arts. 7º, III, e 23."}, {"id": 2000002488, "trilha": "fiscal", "materia": "dados", "assunto": "LGPD", "tipo": "pergunta", "frente": "Qual o valor máximo da multa simples da LGPD?", "verso": "Até 2% do faturamento no Brasil, limitada a R$ 50 milhões por infração.", "explicacao": "LGPD, art. 52, II."}, {"id": 2000002489, "trilha": "fiscal", "materia": "dados", "assunto": "LGPD", "tipo": "pergunta", "frente": "O que é a ANPD?", "verso": "Autoridade Nacional de Proteção de Dados, que fiscaliza e aplica as sanções da LGPD.", "explicacao": "Hoje autarquia de natureza especial."}, {"id": 2000002490, "trilha": "fiscal", "materia": "dados", "assunto": "Análise", "tipo": "pares", "frente": "Análise descritiva x diagnóstica x preditiva x prescritiva.", "verso": "Descritiva: o que aconteceu. Diagnóstica: por que aconteceu. Preditiva: o que vai acontecer. Prescritiva: o que fazer.", "explicacao": ""}, {"id": 2000002491, "trilha": "fiscal", "materia": "dados", "assunto": "Análise", "tipo": "pares", "frente": "Aprendizado supervisionado x não supervisionado.", "verso": "Supervisionado: treina com dados rotulados (classificação, regressão). Não supervisionado: encontra padrões em dados sem rótulos (agrupamento, associação).", "explicacao": "Há também o aprendizado por reforço."}, {"id": 2000002492, "trilha": "fiscal", "materia": "dados", "assunto": "Análise", "tipo": "pares", "frente": "Classificação x regressão (aprendizado de máquina).", "verso": "Classificação: prevê categorias (fraude ou não fraude). Regressão: prevê valores numéricos (valor de arrecadação).", "explicacao": ""}, {"id": 2000002493, "trilha": "fiscal", "materia": "dados", "assunto": "Análise", "tipo": "pergunta", "frente": "O que é clusterização?", "verso": "Técnica não supervisionada que agrupa registros semelhantes entre si, como no algoritmo k-means.", "explicacao": "Ex.: segmentar contribuintes por perfil."}, {"id": 2000002494, "trilha": "fiscal", "materia": "dados", "assunto": "Análise", "tipo": "pergunta", "frente": "O que é overfitting?", "verso": "Quando o modelo se ajusta demais aos dados de treino e generaliza mal para dados novos.", "explicacao": "Usa-se separação entre treino e teste e validação cruzada."}, {"id": 2000002495, "trilha": "fiscal", "materia": "dados", "assunto": "Análise", "tipo": "pergunta", "frente": "O que é a matriz de confusão?", "verso": "Tabela que compara previsões e valores reais: verdadeiros positivos, falsos positivos, verdadeiros negativos e falsos negativos.", "explicacao": "Precisão, recall e acurácia saem dela."}, {"id": 2000002496, "trilha": "fiscal", "materia": "dados", "assunto": "Análise", "tipo": "pares", "frente": "Precisão x recall (sensibilidade).", "verso": "Precisão: dos casos previstos como positivos, quantos são positivos de fato. Recall: dos positivos reais, quantos o modelo encontrou.", "explicacao": ""}, {"id": 2000002497, "trilha": "fiscal", "materia": "dados", "assunto": "Análise", "tipo": "pergunta", "frente": "O que é mineração de dados (data mining)?", "verso": "Processo de descobrir padrões, associações e tendências em grandes conjuntos de dados.", "explicacao": "Parte do processo KDD (descoberta de conhecimento em bases de dados)."}, {"id": 2000002498, "trilha": "fiscal", "materia": "dados", "assunto": "Visualização", "tipo": "pergunta", "frente": "Qual gráfico é mais adequado para mostrar evolução ao longo do tempo?", "verso": "Gráfico de linhas.", "explicacao": "Barras para comparar categorias; dispersão para relação entre duas variáveis."}, {"id": 2000002499, "trilha": "fiscal", "materia": "dados", "assunto": "Visualização", "tipo": "pergunta", "frente": "O que é um dashboard?", "verso": "Painel visual que reúne os principais indicadores, permitindo acompanhamento rápido e tomada de decisão.", "explicacao": "Ex.: Power BI, Tableau."}, {"id": 2000002500, "trilha": "fiscal", "materia": "dados", "assunto": "Formatos", "tipo": "pergunta", "frente": "O que é um arquivo CSV?", "verso": "Arquivo de texto com valores separados por vírgula (ou ponto e vírgula), em que cada linha é um registro.", "explicacao": "Formato simples e amplamente usado para dados abertos."}]$c$::jsonb) as x(id integer, trilha text, materia text, assunto text, tipo text, frente text, verso text, explicacao text)
on conflict (id) do update set trilha = excluded.trilha, materia = excluded.materia, assunto = excluded.assunto, tipo = excluded.tipo,
  frente = excluded.frente, verso = excluded.verso, explicacao = excluded.explicacao, ativa = true, atualizado_em = now();

select trilha, count(*) as cartoes, public.cartoes_versao() as versao from public.cartoes where ativa group by trilha;
